P.entries["npc:innkeeper-keldamyr"] = {n="Innkeeper Keldamyr",s="In Dolanaar, hangiul Keldamyr ofera mancare, bautura si un loc de odihna. Tinerii elfi de noapte care parasesc Shadowglen isi pot gasi adapost la hanul sau, sub ramurile Copacului Lumii.",h="In Dolanaar, hangiul Keldamyr ofera mancare, bautura si un loc de odihna.",kw={"dolanaar","hearthstone","han","innkeeper","keldamyr","night elf","teldrassil"},ang={["race:NightElf"]="In calitate de elf de noapte care paraseste terenul de antrenament al Shadowglen, poti face din hanul lui Keldamyr prima ta casa departe de casa si poti lega Hearthstone acolo."},sec={{t="Vatra Dolanaarului",b="Dolanaar este primul sat pe care multi nou-veniti ajung dupa ce parasesc poiana adapostita din Aldrassil. La hanul central al satului, hangiul Keldamyr ofera paine, apa de izvor si paturi moi sub baldachinul lui Teldrassil. Calatorii, santinelele si tinerii novici indreptati spre Darnassus se opresc la tejgheaua lui pentru a se odihni, a-si lega Hearthstones si a aduna ratii pentru calatoria prin ramuri."},{t="Livrari in oras",b="Un han inalt intre ramuri depinde de aprovizionarea constanta din asezarile din apropiere si meseriasii. Curierii care aduc marfuri sunt adesea trimisi la biroul lui Keldamyr, legandu-si hanul de comertul zilnic care il tine pe Dolanaar sa functioneze."}},faq={{q="Unde il pot gasi pe Innkeeper Keldamyr?",a="Puteti gasi Keldamyr in interiorul hanului principal din inima Dolanaar, prima asezare majora la sud de Shadowglen de pe ramurile lui Teldrassil.",al={"locatia lui Keldamyr","unde este Keldamyr","locatia hangiului din Dolanaar"}},{q="Ce servicii ofera Innkeeper Keldamyr?",a="Keldamyr ofera mancare, bautura si un loc de odihna. Puteti sa va legati Hearthstone la vatra lui, sa cumparati apa, lapte, suc si paine sau sa va deconectati odihnit sub acoperisul lui.",al={"marfurile lui Keldamyr","ce vinde Keldamyr","mancare de han in Dolanaar"}},{q="Ce misiuni il implica pe Innkeeper Keldamyr?",a="Keldamyr primeste colete pentru han prin serviciul de curierat local numit „Livrare Dolanaar”.",al={"keldamyr misiuni","Dolanaar Delivery predare"}}},fx={cc228f0e={q="Cine este Innkeeper Keldamyr?",a="Innkeeper Keldamyr este un hangita elf al noptii care administreaza hanul din Dolanaar. Pe masura ce calatorii strabat poienile umbrite din Shadowglen si meleagurile intinse din Teldrassil, Keldamyr le ofera un camin linistit, bauturi racoritoare si provizii aventurierilor istoviti care calatoresc printre ramurile uriase.",al={"cine este keldamyr","povestea lui innkeeper keldamyr"}},["1430db47"]={q="De partea cui este Innkeeper Keldamyr?",a="Innkeeper Keldamyr este loial lui Darnassus si Alliance. Ii slujeste comunitatii night elf din Dolanaar, deschizandu-si usile pentru elfi si aliati ai Alliance aflati in cautarea odihnei sub bolta lui Teldrassil.",al={"factiunea keldamyr","face keldamyr parte din alliance"}},ff7bce47={q="Ce isi doreste Innkeeper Keldamyr?",a="Keldamyr vrea sa se asigure ca hanul din Dolanaar este bine aprovizionat si primitor. Se ocupa de livrarile de provizii, coordoneaza transporturile locale si se asigura ca fiecare calator are hrana, apa si un loc sigur unde sa-si lege piatra de vatra inainte de a porni in salbaticie.",al={"obiectivele lui keldamyr","ce vrea keldamyr"}},dbe1a8c8={q="De ce se afla Innkeeper Keldamyr aici, in Dolanaar?",a="Dolanaar este principalul nod de drumuri si asezarea celor tineri night elf care pleaca din Shadowglen dupa instruire. Keldamyr tine hanul satului chiar langa drum, oferind adapost si hrana in acest punct de rascruce important din Teldrassil.",al={"de ce se afla keldamyr aici","keldamyr dolanaar"}}},fp="18,175,18.388.0,15.218.0,36.138.0,44.165.0,39.96.0"}
