P.entries["npc:interrogator-vishas"] = {n="Interrogator Vishas",s="Interrogator James Vishas este maestrul supliciilor al Scarlet Crusade, aflat in adancul aripii cimitirului din Scarlet Monastery. Vestit pentru vocea sa stridenta si cruzimea fara margini, isi gaseste o placere bolnava in a-i infrange pe prizonieri si a pune la incercare limitele trupului muritor. Putini dintre cei care intra in camerele sale de tortura mai ies de acolo cu mintea sau trupul intacte.",h="Interrogator James Vishas este maestrul supliciilor al Scarlet Crusade, aflat in adancul aripii cimitirului...",kw={"cimitir","interrogator vishas","james vishas","lordamere lake","nancy vishas","scarlet monastery","tortura","vorrel sengutz"},ang={["class:Priest"]="Sa-l vezi pe Vishas invocand fanatismul pentru a sfinti mutilari ingrozitoare arata intr-un mod cutremurator cum un scop sfant se poate perverti in nebunie.",["faction:Alliance"]="Eroii Aliantei care descopera faptele lui Vishas isi dau repede seama ca Scarlet Crusade nu mai face deosebire intre monstrii Scourge si calatorii nevinovati inca in viata.",["race:Undead"]="Pentru Forsaken, Vishas intruchipeaza rautatea ipocrita a fanaticilor vii: ii tortureaza din pura ura pe mortii-vii capturati, pretinzand in acelasi timp ca slujeste Holy Light."},sec={{t="Scalpelul Marelui Inchizitor",b="In criptele intunecate si cimitirele din Scarlet Monastery, Interrogator Vishas se ocupa de dusmanii capturati ai Crusadei. In timp ce fanaticii de afara marsaluiesc in armuri stralucitoare, sub stindardele puritatii, Vishas reprezinta cruda realitate din spatele cruciadei: sadism fara frau, ascuns sub haina furiei religioase si a dreptatii. El priveste interogatoriul nu doar ca pe o indatorire informativa, ci ca pe o meserie pretioasa, delectandu-se cu agonia captivilor Forsaken, a membrilor Scourge capturati si a calatorilor in viata destul de ghinionisti incat sa fie declarati eretici."},{t="O viata de liniste casnica",b="Dincolo de sorturile insangerate si tipetele camerei de tortura, Vishas duce o viata de familie bizar de obisnuita. In afara zidurilor manastirii, familia sa - inclusiv sotia lui, Nancy Vishas, si ruda sa mai in varsta, Grandpa Vishas - locuieste linistita intr-o casuta izolata de pe tarmul estic al Lordamere Lake, in Alterac Mountains. Vishas duce chiar si suveniruri sinistre de la victimele sale in viata personala: i-a luat verigheta mult pretuita unui Forsaken captiv pe nume Vorrel Sengutz, ca sa i-o ofere lui Nancy."}},faq={{q="Unde poate fi gasit Interrogator Vishas?",a="Interrogator Vishas se afla adanc in aripa Cimitirului din Scarlet Monastery, in Tirisfal Glades. El supravegheaza o camera sumbra de tortura, captusita cu custi de fier si rasteluri insangerate.",al={"locatia lui Vishas","unde este Interrogator Vishas","camera lui Vishas"}},{q="De ce isi tortureaza Vishas prizonierii?",a="Desi Scarlet Crusade justifica chinuirea prizonierilor ca mijloc de a descoperi coruptia Scourge si de a obtine informatii, Vishas se bucura personal de durerea pe care o provoaca. Este nespus de mandru de cruzimea sa, considerand tortura o arta.",al={"de ce ii tortureaza Vishas pe oameni","motivul lui Vishas"}},{q="Cine este Vorrel Sengutz?",a="Vorrel Sengutz este un prizonier inchis si torturat cu cruzime de Vishas in cimitirul manastirii. Vishas l-a supus pe Vorrel saptamani intregi de suferinta si i-a furat verigheta, cu intentia de a i-o darui sotiei sale.",al={"prizonierul vorrel sengutz","cine este prizonierul din cusca"}},{q="Unde locuieste familia lui Vishas?",a="Familia lui locuieste departe de Manastire, intr-o casuta modesta de pe malul estic al Lordamere Lake, in Alterac Mountains. Sotia sa, Nancy, si bunicul Vishas duc o viata linistita acolo, parand neafectati de atrocitatile lui.",al={"locatia lui Nancy Vishas","bunicul Vishas","casa familiei Vishas"}},{q="Pe cine tine Vishas prizonier?",a="Scarlet Crusade ii considera dusmani pe cei strigoi. Printre prizonierii lui Vishas se numara Forsaken Vorrel Sengutz, pe care l-a torturat vreme de saptamani.",al={"prizonierii lui vishas","pe cine tortureaza vishas","captivul vorrel al lui vishas"}},{q="Cum sunt vocea si comportamentul lui Vishas?",a="Vishas este vestit printre cei care-l infrunta pentru vocea sa stridenta si subtire, rasul batjocoritor si entuziasmul nelinistitor pe care-l arata ori de cate ori i se iveste prilejul sa smulga secrete de la o victima impotriva vointei ei.",al={"vocea lui vishas","personalitatea lui vishas"}}},fx={["518fe48c"]={q="Cine este Interrogator Vishas?",a="James Vishas este anchetatorul-sef al Scarlet Crusade, aflat in adancurile cimitirului din Scarlet Monastery. Fanatic si notoriu pentru cruzimea sa, este nespus de mandru cand reuseste sa-i infranga pe prizonierii adusi in fata lui. Inarmat cu instrumente de tortura si cu un zel nestapanit, smulge marturisiri si provoaca chinuri in egala masura oricui are nenorocul sa-i cada in maini.",al={"cine este Vishas","povestea lui Interrogator Vishas","cine este James Vishas"}},cadee917={q="De partea cui este Interrogator Vishas?",a="Vishas este pe deplin devotat Scarlet Crusade. Ii slujeste cruciadei zeloase torturand suspecti de a fi agenti Scourge, prizonieri Forsaken si pe oricine altcineva considerat corupt sau ostil puritatii fanatice a ordinului.",al={"factiunea lui vishas","pentru cine lucreaza vishas","vishas si Scarlet Crusade"}},e1510cf6={q="De ce se afla aici Interrogator Vishas?",a="Vishas este stationat in camerele de tortura din Scarlet Monastery Graveyard, unde se ocupa de prizonierii capturati prin Tirisfal Glades. Isi petrece zilele si noptile smulgand informatii, dandu-si frau liber pornirilor sadice si frangand vointa captivilor precum Vorrel Sengutz, in numele Cruciadei.",al={"de ce este Vishas in cimitir","rolul lui Vishas la manastire","ce face Vishas aici"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
