P.entries["npc:marcus-redpath"] = {n="Marcus Redpath",s="Marshal Marcus Redpath este cea mai inalta autoritate militara care apara orasul Alliance Southshore din Hillsbrad Foothills. El organizeaza patrule si contracte cu recompense pentru a tine la distanta ogrii, murlocii si naga din imprejurimi. Conducerea sa este esentiala pentru pastrarea ultimului bastion sudic al Lordaeronului de pe coasta.",h="Marshal Marcus Redpath este cea mai inalta autoritate militara care apara orasul Alliance Southshore din...",kw={"Crushridge","Hillsbrad","Marcus Redpath","maresal","Southshore"},ang={["faction:Alliance"]="Marshal Redpath le incredinteaza campionilor Alliance misiuni esentiale pentru a apara Hillsbrad de ogrii care se apropie si de pericolele de pe coasta.",["race:Human"]="Redpath pastreaza una dintre ultimele redute ale omenirii in Lordaeron, mentinand Southshore in picioare, in timp ce regatul din jur se naruie."},sec={{t="O santinela din Southshore",b="Marcus Redpath este maresalul din Southshore, portul Alliance de pe coasta sudica a Hillsbrad Foothills. Southshore a supravietuit caderii capitalei Lordaeron si invaziei devastatoare a Scourge, iar acum Redpath se afla in fruntea apararii sale, pazind supravietuitorii greu incercati ai portului."},{t="Apararea coastei",b="Dupa Third War, Southshore a ramas aproape singur impotriva fortelor ostile care se strang din toate partile. Marshal Redpath coordoneaza operatiunile de aparare din Hillsbrad Foothills, recrutand aventurieri incercati pentru a-i respinge pe ogrii Crushridge care coboara din Alterac si pentru a curata taberele primejdioase de naga si murloci de-a lungul coastei. Cu Forsaken ocupand nordul si Tarren Mill puternic fortificat in apropiere, vigilenta lui Redpath este una dintre putinele bariere care impiedica prezenta Alliance din regiune sa se prabuseasca de tot."}},faq={{q="Cine este Marcus Redpath?",a="Marcus Redpath este maresalul si comandantul militar al Southshore din Hillsbrad Foothills. Supravegheaza apararea locala impotriva pericolelor din tinuturile salbatice din jur si a vecinilor ostili.",al={"povestea lui Marcus Redpath","cine este maresalul din Southshore","informatii despre Marcus Redpath"}},{q="Ce rol a avut in Second War?",a="Nicio relatare despre Second War nu consemneaza rolul lui Redpath in aceasta. Astazi este cunoscut drept maresalul din Southshore, aparand orasul de ogrii, murlocii si nagii din Hillsbrad Foothills.",al={"second war marcus","s-a intalnit marcus redpath cu lothar"}},{q="Impotriva caror amenintari lupta in principal?",a="Redpath organizeaza actiunile militare impotriva pradatorilor si invadatorilor locali care ameninta Southshore. El ofera recompense si misiuni impotriva tribului ogre Crushridge din poalele muntilor Alterac, a murlocilor de pe coasta si a naga care ataca.",al={"misiunile lui Marcus Redpath","ce vrea Redpath sa fie ucis"}},{q="Are vreo legatura cu familia Redpath din Darrowshire?",a="Desi poarta acelasi nume de familie Redpath, facut celebru de Captain Joseph Redpath din Darrowshire, in Eastern Plaguelands, nu a fost stabilita oficial nicio legatura de rudenie directa, dincolo de mostenirea comuna din Kingdom of Lordaeron.",al={"familia Redpath","este Marcus ruda cu Joseph Redpath?","rudele familiei Redpath"}},{q="Unde poate fi gasit Marcus Redpath?",a="Marshal Redpath se afla in centrul localitatii Southshore, un refugiu Alliance de pe coasta sudica a regiunii Hillsbrad Foothills.",al={"unde este marcus redpath","locatia lui marcus redpath"}}},fx={["0aeeadbf"]={q="De partea cui este Marcus Redpath?",a="Maresalul Marcus Redpath serveste Alliance si supravietuitorii din Lordaeron, adunati sub stindardul Southshore. In calitate de maresal al orasului Southshore, el este un sustinator ferm al aparatorilor umani care tin linia din Hillsbrad impotriva amenintarilor ostile din tinuturile deluroase.",al={"factiunea lui Marcus Redpath","din ce factiune face parte Marcus Redpath","cui ii slujeste Redpath"}},["43107ef7"]={q="Ce vrea Marcus Redpath?",a="Redpath vrea sa apere Southshore si tinuturile din jur de primejdiile care se apropie. Le da soldatilor si aventurierilor misiunea de a elimina amenintarile din regiune, respingand triburile de capcauni Crushridge din muntii nordici si starpind napadirile de murloci si naga care bantuie coasta.",al={"obiectivele lui Marcus Redpath","de ce are nevoie Redpath","scopul lui Marcus Redpath"}},["402d4dad"]={q="De ce se afla Marcus Redpath aici?",a="Marcus Redpath este maresalul din Southshore. De la caderea Lordaeronului in Third War, orasul a fost unul dintre ultimele bastioane ale Alliance din regiune, iar el ii organizeaza apararea si mentine ordinea.",al={"de ce este marcus redpath in southshore","motivul pentru redpath southshore","ce face redpath aici"}}},fp="14,308,24.295.0,17.550.0,22.182.0,40.182.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="Mardant Strongoak",s="Mardant Strongoak este un instructor druid elf al noptii, care locuieste in Aldrassil, in inima Teldrassilului. El ii indruma pe druizii in devenire sa comunice cu spiritele naturii si le dezvaluie misterele Emerald Dream.",h="Mardant Strongoak este un instructor druid elf al noptii, care locuieste in Aldrassil, in inima...",kw={"aldrassil","druid","emerald dream","mardant","shadowglen","strongoak","teldrassil","antrenor"},ang={["class:Druid"]="Pentru tinerii druizi elfi ai noptii, Mardant Strongoak este prima punte dintre viata obisnuita si indatoririle sacre ale Cenarion Circle.",["race:NightElf"]="Aflat in inima Aldrassil, Mardant este un exemplu al devotamentului kaldorei fata de armonizarea cu ecosistemul in plina dezvoltare al Teldrassil."},sec={{t="Instructorul salbaticiei",b="In coroana lui Aldrassil, tinerii Night Elves care simt chemarea salbaticiei apeleaza la Mardant Strongoak. Sarcina lui principala este sa-i invete pe novici sa-si deschida simturile catre spiritele naturii, sa le inteleaga murmurul si sa canalizeze magii regeneratoare. Pentru cei care fac primii pasi ca aparatori ai salbaticiei, el este adesea primul maestru care le dezvaluie complexitatea vasta si pericolele stravechi ale Emerald Dream."}},faq={{q="Cine este Mardant Strongoak?",a="Mardant Strongoak este un instructor Druid Night Elf, stationat in Shadowglen, in Aldrassil. Ii indruma pe druizii abia treziti din Teldrassil in tainele de baza ale comuniunii si vrajitoriei.",al={"lore despre Mardant Strongoak","cine este Mardant","Mardant din Aldrassil"}},{q="Ce ii invata pe noii druizi?",a="Ii invata pe novici sa descifreze mesajele spiritelor salbatice, sa rosteasca vraji simple precum Moonfire si incantatii de vindecare, precum si sa inteleaga natura Emerald Dream.",al={"ce invata Mardant","abilitatile lui Mardant","instructorul Druid din Shadowglen"}},{q="Unde il pot gasi pe Mardant Strongoak?",a="Se afla in interiorul sau in apropierea lui Aldrassil, in Shadowglen, valea de inceput pentru aventurierii elfi ai noptii de pe Teldrassil.",al={"locatia lui mardant","unde se afla mardant strongoak"}},{q="Ce este Verdant Sigil?",a="Verdant Sigil este un jeton de instruire oferit tinerilor druizi night elf din Shadowglen, indrumandu-i sa-l caute pe Mardant Strongoak pentru primele lectii.",al={"misiunea verdant sigil","sigil pentru mardant"}}},fx={a3bbc1b2={q="De partea cui este Mardant Strongoak?",a="Mardant Strongoak este devotat elfilor noptii, Alliance si principiilor sacre ale Cenarion Circle. El ramane neclintit in Shadowglen pentru a ocroti tanarul World Tree si a se asigura ca traditiile druidilor kaldorei dainuie in aceste vremuri nesigure.",al={"factiunea lui Mardant Strongoak","cui ii este loial Mardant","este Mardant de partea Aliantei?"}},ff8559f4={q="Ce doreste Mardant Strongoak?",a="Mardant vrea ca tinerii initiati Night Elf sa-si aprofundeze legatura cu natura. El isi propune sa-i indrume pe noii druizi prin primele lor incercari, ajutandu-i sa desluseasca soaptele spiritelor si sa infrunte misterele si primejdiile profunde din Emerald Dream.",al={"ce vrea Mardant","obiectivele lui Mardant Strongoak","care este scopul lui Mardant"}},b78651d9={q="De ce se afla Mardant Strongoak aici?",a="Aflat in ramurile scobite ale lui Aldrassil, Mardant le este mentor druidilor proaspat treziti, care fac primii pasi in Teldrassil. El ramane in Shadowglen pentru a veghea asupra novicilor, a-i invata despre puterile lor innascute si a-i indruma catre cei care au nevoie de ajutor in toata poiana.",al={"de ce este mardant in aldrassil","de ce este mardant strongoak aici","motivul pentru care mardant strongoak se afla aici"}},dec3bef7={q="Cu cine are legaturi Mardant Strongoak?",a="Mardant este strans legat de Cenarion Circle si de ceilalti invatatori din Aldrassil, precum preotesele lui Elune si Sentinels care pazesc sanctuarul. Impreuna, ii indruma si ii cresc pe tinerii aparatori Night Elf.",al={"aliatii lui mardant strongoak","cu cine este asociat mardant","legaturile lui mardant"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marisa-du-paige"] = {n="Marisa du'Paige",s="In pesterile din afara Deadmines, Marisa du'Paige lupta alaturi de haiducii din Moonbrook. Rara printre muncitorii si talharii lor de drum, ea foloseste magie arcana in tunelurile din sud-vestul Westfall.",h="In pesterile din afara Deadmines, Marisa du'Paige lupta alaturi de haiducii din Moonbrook.",kw={"deadmines","human","mage","marisa du'paige","marisa dupaige","moonbrook","rar","westfall"},ang={["class:Mage"]="Marisa du'Paige demonstreaza ca pregatirea arcane din regat depaseste turnurile Kirin Tor si sanctumul vrajitorilor din Stormwind. Vrajitorii renegati isi vand de bunavoie talentele retelelor criminale.",["faction:Alliance"]="Ca aventurier din Alliance, fii cu ochii in patru dupa du'Paige in tunelurile de sub Moonbrook. Un vrajitor neasteptat printre hotii de buzunare poate transforma rapid o incaierare intr-o lupta mortala."},sec={{t="Talent arcane in tuneluri",b="In adancul pesterilor care duc spre Deadmines, sub Moonbrook, hoti de buzunare, mineri renegati si batausi pazesc tunelurile. Marisa du'Paige este un Mage Human iscusit printre ei. Multi vrajitori se pregatesc in Mage Quarter din Stormwind sau slujesc Kirin Tor, dar Marisa s-a alaturat proscrisilor si banditilor din pasajele subterane ale Westfall."}},faq={{q="Cine este Marisa du'Paige?",a="Marisa du'Paige este o mage Human rara, aflata in pesterile de la intrarea in Deadmines. In timp ce hotii si muncitorii de rand patruleaza aceste pasaje, ea foloseste vraji arcane pentru a apara reteaua subterana.",al={"Marisa Dupaige","cine este Marisa","inamic rar in pestera din Deadmines"}},{q="Unde poate fi gasita?",a="Marisa du'Paige apare rar in reteaua de pesteri publice de sub Moonbrook, in Westfall, in tunelurile aflate chiar dincolo de pragul portalului catre instanta Deadmines.",al={"locatia lui Marisa du'Paige","unde este Marisa dupaige","aparitia Marisei"}},{q="De ce se ascunde un mag human in pesterile din Deadmines?",a="Unii practicanti ai artelor arcane parasesc turnurile inalte din Stormwind. Deserters, renegati si oameni de rand plini de compasiune s-au alaturat cauzei proscrisilor in Westfall, aducand otel si vrajitorie in bastioanele lor de sub Moonbrook.",al={"de ce e ea aici","povestea lui marisa","factiunea lui marisa dupaige"}}},fx={["5e8e0d23"]={q="De partea cui este Marisa du'Paige?",a="Marisa du'Paige poarta vesmintele si strabate salile subterane ale Defias Brotherhood. Pandind adanc in pesterile din Moonbrook, care duc spre Deadmines, ea se alatura fratiei razvratite a lui Edwin VanCleef si isi arunca vrajile arcane asupra oricarui intrus care le ameninta fortareata.",al={"factiunea Marisei Dupaige","Marisa Dupaige face parte din Defias","pentru cine lucreaza Marisa Dupaige"}}},fp="15,191,28.333.0,23.200.0,23.164.0,50.217.0"}
P.entries["npc:marshal-dughan"] = {n="Marshal Dughan",s="Marechalul din Goldshire se confrunta cu amenintari pe fiecare drum si in fiecare mina. Marshal Dughan comanda detasamentul Stormwind Army de acolo, dar kobolds, gnolli si banditi pun la grea incercare mica sa garnizoana. El depinde de aventurieri independenti pentru a apara orasul si fermele din apropiere.",h="Marechalul din Goldshire se confrunta cu amenintari pe fiecare drum si in fiecare mina.",kw={"elwynn forest","fargodeep","goldshire","hogger","jasperlode","marshal dughan","armata stormwind","westbrook garrison"},ang={["class:Warrior"]="Ca Warrior, vezi cum pedestrasii din Stormwind tin linia cu disciplina, in ciuda sanselor imposibile si a numarului prea mic de soldati.",["faction:Alliance"]="Ca recruta din Alliance in Elwynn, primesti primele misiuni militare de la Marshal Dughan, autoritatea locala din Stormwind."},sec={{t="Comandantul din Crossroads",b="Marshal Dughan conduce apararea din Elwynn Forest de la Goldshire, in fata Lion's Pride Inn. Soldatii din Stormwind sunt prinsi in alte parti, iar necazurile din padure se inmultesc. Kobolds misuna prin mine, gnolls se aduna pe malurile raurilor, iar talharii ataca drumetii pe King's Road. Avand prea putini pedestrasi sub comanda, Dughan trimite recruti noi sa intareasca avanposturile si sa cerceteze zonele periculoase."},{t="Amenintari la toate granitele",b="Kobolds au napadit Fargodeep si Jasperlode Mines, amenintand aprovizionarea cu minerale a Goldshire. La vest de oras, gnoll-ii Riverpaw ai lui Hogger pun presiune asupra Westbrook Garrison. La est, Guard Thomas raporteaza ca murlocs feroce ucid patrulele de-a lungul raului. Dughan are prea putini soldati pentru a face fata fiecarei amenintari, asa ca are nevoie de mercenari priceputi care sa-l ajute sa le tina sub control."}},faq={{q="Cine este Marshal Dughan?",a="Marshal Dughan comanda un detasament al Stormwind Army in Goldshire. El coordoneaza apararea din Elwynn Forest impotriva hotilor, gnoll-ilor si kobold-ilor.",al={"Dughan","povestea lui Marshal Dughan","marshalul din Goldshire"}},{q="De ce nu trimite Dughan mai multi gardieni sa ajute Westbrook Garrison sau partea de est?",a="Fortele celor din Stormwind sunt rasfirate, iar Dughan abia are destui gardieni ca sa pastreze ordinea in Goldshire. Nu are suficienti soldati pentru fiecare ferma si post de frontiera, asa ca se bazeaza pe aventurierii aflati in trecere sa cerceteze pericolele, sa duca ordine si sa infrunte amenintarile locale.",al={"de ce nu sunt garzi","efectivele garnizoanei din Goldshire","trupele lui Dughan"}},{q="Ce parere are Dughan despre amenintarea murlocilor din Elwynn?",a="Dughan a respins la inceput avertismentele lui Remy 'Two Times' despre amenintarea reprezentata de murlocs in regiune. Rapoartele lui Guard Thomas despre mortile lui Rolf Hartford si Malakai Stone de-a lungul apelor estice l-au convins ca pericolul era real.",al={"murlocii lui dughan","remy de doua ori murloc","oameni-pesti dughan"}},{q="Cum se ocupa Dughan de infractiunile locale si de civilii turbulenti?",a="Dughan are sarcina de a mentine pacea in Goldshire si in tinuturile din imprejurimi. Spune ca e destul de greu sa pastreze ordinea in mijlocul noilor probleme din Elwynn si se concentreaza asupra koboldilor din nord si a gnollilor si hotilor din vest.",al={"crima lui dughan","legea din goldshire","amenintarea stockade"}},{q="De ce este Dughan ingrijorat de mine?",a="Fargodeep Mine si Jasperlode Mine ii furnizeaza Stormwindului aur si minereu. Kobolds au napadit ambele mine, i-au alungat pe mineri si ameninta sa sape tuneluri pe sub asezarile din Elwynn.",al={"fargodeep mine dughan","jasperlode mine dughan","infestare cu kobold"}},{q="Colaboreaza Marshal Dughan cu Westfall?",a="Da. Dupa ce un aventurier isi dovedeste capacitatea in Elwynn Forest, Dughan il trimite sa se prezinte la Gryan Stoutmantle, in Sentinel Hill din Westfall. People's Militia are nevoie de ajutorul unui veteran impotriva Defias Brotherhood.",al={"dughan gryan","raporteaza in westfall","dughan sentinel hill"}}},fx={["72888056"]={q="De partea cui este Marshal Dughan?",a="Marshal Dughan slujeste Kingdom of Stormwind si Alliance. Ca ofiter in Stormwind Army, raspunde direct ierarhiei militare a regatului si indeplineste ordinele coroanei de a mentine ordinea si a proteja tinuturile centrale, in ciuda imputinarii intaririlor regale.",al={"factiunea lui dughan","pe cine slujeste dughan","loialitatea lui marshal dughan"}},["9141816c"]={q="Ce vrea Marshal Dughan?",a="Dughan vrea sa securizeze Elwynn Forest si sa apere Goldshire de amenintarile tot mai numeroase. Cu garnizoana sa intinsa la maximum, cauta aventurieri capabili sa cerceteze minele Fargodeep si Jasperlode, infestate, sa tina in frau banditii Defias si gnollii din vest si sa evalueze pericolul tot mai mare de-a lungul malurilor raului.",al={"scopul lui Dughan","de ce are nevoie Dughan","obiectivele lui Dughan"}},["8808e7de"]={q="De ce este Marshal Dughan stationat in Goldshire?",a="Dughan este stationat in Goldshire in calitate de comandant al detasamentului local Stormwind Army. Insarcinat cu apararea centrului regiunii Elwynn, el supravegheaza mentinerea ordinii in oras, coordoneaza avanposturi precum Westbrook Garrison si organizeaza apararea impotriva fiarelor, kobolzilor si infractorilor care ameninta granarul capitalei.",al={"de ce se afla Dughan in Goldshire","scopul lui Marshal Dughan aici","postul lui Dughan"}},["156c33b1"]={q="Cu cine este asociat Marshal Dughan?",a="Dughan colaboreaza indeaproape cu comandantii avanposturilor locale din Elwynn, precum Deputy Rainer de la Westbrook Garrison si Guard Thomas, aflat de-a lungul podurilor estice. In afara Elwynn, tine legatura cu camarazi din armata precum Gryan Stoutmantle din Westfall, impartasindu-le informatii despre activitatile infractionale din regiune.",al={"legaturile lui Dughan","cu cine lucreaza Dughan","aliatii lui Dughan"}}},fp="14,260,27.399.0,23.343.0,22.143.0,75.260.0,53.208.1,55.213.0,40.179.0,45.208.0"}
P.entries["npc:marshal-marris"] = {n="Marshal Marris",s="Marshal Marris este ofiterul militar coplesit de situatie care comanda garda orasului Lakeshire. Stationat langa podul orasului, coordoneaza operatiunile de aparare impotriva uriasei invazii a orcilor Blackrock, care coboara din inaltimile din Redridge Mountains. In lipsa armatei Stormwind, se bazeaza pe aventurierii aflati in trecere pentru a opri inaintarea hoardei.",h="Marshal Marris este ofiterul militar coplesit de situatie care comanda garda orasului Lakeshire.",kw={"Blackrock","pod","Lakeshire","Marris","Marshal Marris","Redridge","Stonewatch","Tharil'zun"},ang={["class:Warrior"]="Marris apreciaza disciplina martiala directa si trimite luptatori capabili din prima linie in gura lupului la Stonewatch, pentru a se infrunta cu veteranii Blackrock caliti in lupta.",["faction:Alliance"]="Marshal Marris intruchipeaza situatia grea a teritoriilor rurale ale Alliance, lasate vulnerabile de paralizia politica din Stormwind si silite sa lupte singure pentru supravietuire.",["race:Human"]="Pentru oamenii regatului, Marris intruchipeaza strajerul de frontiera stoic si greu incercat, care tine piept ramasitelor din Old Horde."},sec={{t="Un oras sub asediu",b="Lakeshire se afla in pragul prabusirii, prinsa intre gnolii din vest si teribila forta militara a Blackrock clan din est. Marshal Marris supravegheaza linia de garda de la podul principal al orasului, dar resursele sale sunt epuizate, iar soldatii sai sunt raspanditi peste o zona imposibil de aparat. Cum regatul Stormwind refuza sa trimita intariri regale, Marris poarta povara grea de a impiedica asezarea sa fie coplesita prin forta bruta."},{t="Zdrobirea avangardei Blackrock",b="Intelegand ca doar apararea nu va salva Redridge, Marris pune la cale lovituri ofensive hotaratoare impotriva taberelor orcilor. Le ordona mercenarilor sa-i elimine pe razboinicii Blackrock, sa le distruga vrajitorii umbrelor si, in cele din urma, sa-l vaneze pe Tharil'zun, comandantul amenintator intarit in ruinele din Stonewatch Keep. Ordinele sale urmaresc sa rupa structura de comanda a orcilor inainte ca un asalt total sa nimiceasca Lakeshire."}},faq={{q="Cine este Marshal Marris?",a="Marshal Marris este comandantul militar superior insarcinat cu apararea orasului Lakeshire. Poate fi gasit de straja langa capatul vestic al podului orasului, incercand sa mentina asezarea fortificata impotriva incursiunilor ostile.",al={"Marris","povestea lui Marshal Marris","cine este gardianul de la podul din Lakeshire"}},{q="De ce angajeaza Marshal Marris aventurieri independenti?",a="Kingdom of Stormwind nu a trimis intariri suficiente garnizoanei din Redridge Mountains, lasand garda locala din Lakeshire cu mult depasita numeric. Confruntat cu bande de gnolli si cu o invazie bine inradacinata a orcilor Blackrock, Marris este nevoit sa recruteze eroi mercenari pentru a duce la indeplinire atacuri esentiale.",al={"de ce are nevoie de ajutor marris","de ce nu exista armata stormwind"}},{q="Impotriva caror amenintari lupta Marshal Marris?",a="Desi gnollii terorizeaza tinuturile de la margine, Marris se concentreaza mai ales asupra orcilor Blackrock, care au pus stapanire pe Stonewatch Keep. Condusi de Tharil'zun si intariti de magia umbrelor, acesti orci reprezinta o amenintare existentiala iminenta pentru Lakeshire si intregul regat.",al={"dusmanii lui marris","cine ataca Lakeshire"}},{q="Are Marshal Marris vreo legatura cu Nathanos Marris?",a="Poarta un nume de familie raspandit in regatele umane din Lordaeron si Stormwind, dar nicio inregistrare oficiala nu confirma o legatura de rudenie directa intre Marshal Marris, din Redridge, si renumitul ranger Nathanos Marris, din nord.",al={"este marris ruda cu nathanos","marris familia"}},{q="Care este planul lui Marris pentru a-i invinge pe cei din Blackrock clan?",a="Marris duce un razboi de uzura si decapitare. El le cere combatantilor sa elimine infanteristii Blackrock, sa adune componente magice de la utilizatorii magiei umbrelor si sa patrunda in Stonewatch Keep pentru a-l executa pe conducatorul lor, Tharil'zun.",al={"planul lui marris","cum sa-i invingi pe orcii din Blackrock"}},{q="Unde poate fi gasit Marshal Marris?",a="Marris se afla in Lakeshire, in Redridge Mountains, intr-un loc vizibil de pe podul din apropierea centrului orasului.",al={"locatia lui Marris","unde se afla Marshal Marris"}}},fx={["4fad023e"]={q="De partea cui este Marshal Marris?",a="Marshal Marris este un ofiter loial Kingdom of Stormwind si Alliance. Stationat pe linia intai din Lakeshire, reprezinta autoritatea militara locala, care incearca cu disperare sa-i apere pe locuitorii din Redridge Mountains de dusmanii care se apropie.",al={"factiunea lui Marshal Marris","cui ii slujeste Marris","Marris este din Alianta sau din Stormwind"}},["4230d686"]={q="De ce se afla Marshal Marris aici, in Lakeshire?",a="Marshal Marris este stationat langa podul din Lakeshire pentru a coordona apararea impotriva orcilor Blackrock care ies din munti. Cum intaririle oficiale din Stormwind sunt rare, el pazeste Redridge si aduna orice aventurier capabil, dispus sa duca lupta pana la fortareata dusmanului.",al={"de ce este Marshal Marris in Redridge","de ce este Marris aici","motivul pentru care Marshal Marris se afla aici"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Marshal Maxwell",s="Marshal Maxwell este un ofiter de rang inalt al armatei Stormwind, stationat la Morgan's Vigil, in Burning Steppes. Insarcinat sa apere creasta fortificata cea mai nordica a Alliance, deasupra Redridge Mountains, impotriva Blackrock clan si a piticilor Dark Iron, el coordoneaza misiuni de cercetare in stancariile ostile de dedesubt. De asemenea, joaca un rol crucial in coordonarea eforturilor de a afla soarta camaradului sau capturat, Marshal Reginald Windsor.",h="Marshal Maxwell este un ofiter de rang inalt al armatei Stormwind, stationat la Morgan's Vigil, in Burning...",kw={"blackrock depths","burning steppes","general drakkisath","marshal maxwell","maxwell","morgans vigil","reginald windsor","armata Stormwind"},ang={["class:Warrior"]="Maxwell intruchipeaza disciplina armatei de pe linia intai a Stormwindului, stand neclintit in mijlocul cenusii vulcanice si coordonand atacurile in adancul teritoriului inamic.",["faction:Alliance"]="Pentru campionii din Alliance care infrunta arsita dogoritoare din Burning Steppes, Marshal Maxwell intruchipeaza autoritatea Stormwind si varful de lance al campaniei impotriva Blackrock Mountain."},sec={{t="Un avanpost izolat in stepa",b="Morgan's Vigil este un avanpost precar de la marginea sudica a Burning Steppes, cu vedere spre un tinut pustiit, napadit de cenusa, dragonkin si orci Blackrock. Marshal Maxwell comanda aici detasamentul militar din Stormwind, oferind o rara priveliste prietenoasa calatorilor care infrunta crestele de foc. Din acest bastion stancos, el supravegheaza manevrele defensive menite sa tina sub control fortele ostile ale muntelui, inainte ca acestea sa se napusteasca spre sud, in Redridge si Elwynn."},{t="Dezvaluirea adevarului in munte",b="Dincolo de sarcinile obisnuite de paza, Maxwell este principalul reprezentant de teren pentru operatiunile menite sa ajunga in inima Blackrock Spire si Blackrock Depths. Cand apar zvonuri ca Marshal Reginald Windsor, capturat, ar mai putea fi in viata in temnitele piticilor Dark Iron, Maxwell este cel care primeste informatiile, cerceteaza rapoartele si le da campionilor de incredere misiunea de a organiza o salvare. Avanpostul sau este puntea esentiala care leaga recunoasterea de la frontiera de tulburarile politice ce mocnesc in spatele portilor Stormwind."}},faq={{q="Cine este Marshal Maxwell?",a="Marshal Maxwell este un comandant al armatei Stormwind, stationat la Morgan's Vigil, in Burning Steppes. El conduce fortele locale ale Alliance care ii supravegheaza pe orcii Blackrock, dragonii Black si piticii Dark Iron.",al={"povestea lui marshal maxwell","cine este maxwell"}},{q="De ce este Marshal Maxwell stationat la Morgan's Vigil?",a="Morgan's Vigil este tabara de prima linie a Alliance, la granita cu Burning Steppes. Maxwell este stationat aici pentru a securiza trecatoarea montana care coboara spre Redridge Mountains si pentru a supraveghea amenintarile ce se revarsa din Blackrock Mountain.",al={"de ce este Maxwell in Burning Steppes","comandantul de la Morgan's Vigil"}},{q="Ce legatura are Maxwell cu Marshal Windsor?",a="Maxwell este comandantul principal care ajuta la cautarea maresalului Reginald Windsor, capturat si tarat in Blackrock Depths. Maxwell ajuta la coordonarea eforturilor de salvare si trimite la Stormwind informatii esentiale despre Windsor.",al={"maxwell si windsor","povestea misiunii Abandoned Hope"}},{q="Il ajuta Marshal Maxwell la organizarea atacurilor impotriva Blackrock Spire?",a="Da. Maxwell le porunceste campionilor veterani ai Alliance sa inlature conducerea de varf a Blackrock clan, emitand ordine pentru eliminarea lui General Drakkisath si a fortelor sale, care tin sub control inaltimile din Blackrock Spire.",al={"maxwell drakkisath","misiunea lui maxwell"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Marshal McBride",s="La Northshire Abbey, Marshal McBride comanda garnizoana din Stormwind si apara valea. Kobolds ameninta fermele si minele, asa ca ii trimite pe noii recruti sa lupte impotriva lor.",h="La Northshire Abbey, Marshal McBride comanda garnizoana din Stormwind si apara valea.",kw={"Douglas McBride","Echo Ridge","Elwynn","kobold","Marshal McBride","Northshire","Northshire Abbey"},ang={["class:Warrior"]="Ca warrior, poti sluji regatul ajutandu-l pe McBride sa curete kobold din tunelurile Echo Ridge.",["faction:Alliance"]="Ca recrut al Alliance, incepi la frontiera Grand Alliance din tinutul natal al Humanilor, unde McBride ii primeste pe recruti in slujba Coroanei.",["race:Human"]="Ca Human care isi incepe calatoria in Northshire, il intalnesti mai intai pe Marshal McBride, autoritatea regala din Stormwind in vale."},sec={{t="Comandantul din Northshire",b="Marshal McBride conduce garnizoana din Stormwind, aflata in afara Northshire Abbey. Manastirea este un loc de credinta si invatatura, in timp ce tulburarile din regat au lasat garnizoanele militare fara suficienti soldati. Cu doar o mana de garzi jurate, McBride trebuie sa mentina pacea in vale si sa-i protejeze hrana si resursele. Recruti lipsiti de experienta sosesc pentru a se instrui sub indrumarea maestrilor manastirii, iar el trebuie sa-i puna la treaba."},{t="Incursiunea kobold",b="Kobolds au devenit mai agresivi in jurul Northshire. Odinioara doar o pacoste, s-au raspandit prin paduri si au pus stapanire pe Echo Ridge Mine, o resursa locala importanta. Din lipsa soldatilor permanenti, McBride le cere ajutorul celor din clasele Paladin si Warrior, precum si altor novici, pentru a respinge koboldii care sapa galerii si a afla cat de departe se intinde infestarea, inainte ca valea sa fie izolata."}},faq={{q="Cine este Marshal McBride?",a="Marshal McBride comanda garnizoana din Stormwind de la Northshire Abbey. El apara Northshire Valley si ii trimite pe noii recruti in slujba.",al={"Marshal McBride","cine este McBride","comandantul din Northshire"}},{q="De ce ii pune McBride pe recruti sa lupte cu kobolds?",a="Kobold au cotropit padurile din jurul Northshire si au ocupat Echo Ridge Mine. Cu fortele din Stormwind raspandite pe fronturi, McBride trimite aventurieri proaspat sositi sa-i alunge si sa securizeze zona.",al={"de ce sa omori koboldi","problema koboldilor","problema din echo ridge"}},{q="Unde ii trimite McBride apoi pe recruti?",a="Dupa ce un recrut se ocupa de amenintarile din Northshire Valley, McBride il trimite spre sud, pe drum, la Goldshire, ca sa-l ajute pe Marshal Dughan.",al={"unde merg dupa McBride","dupa Northshire","urmatorul oras"}},{q="Ce este Echo Ridge Mine?",a="Echo Ridge Mine este o caverna bogata in minereuri, aflata la marginea nordica a Northshire Valley. Kobold au invadat-o, iar McBride a ordonat mai multe incercari de recucerire.",al={"echo ridge","mina din northshire"}},{q="Conduce McBride insasi abatia?",a="Nu. Northshire Abbey este ingrijita de ordinele sfinte si de preotii Light. McBride comanda garnizoana militara care apara abatia si valea din imprejurimi.",al={"McBride conduce Northshire Abbey","cine este responsabil de abatie"}},{q="Il ingrijoreaza pe McBride amenintari dincolo de koboldi?",a="Kobold-ii sunt principala preocupare a lui McBride, dar banditii si proscrisii pandesc la marginile vaii, semne ale unor tulburari mai ample in Elwynn Forest.",al={"defias in Northshire","este Northshire in siguranta"}}},fx={["05ea779e"]={q="De partea cui este Marshal McBride?",a="Marshal McBride este un ofiter loial al Stormwind Army si al Grand Alliance. El raspunde in fata coroanei din Stormwind si vegheaza asupra Northshire Valley, pentru a asigura siguranta cetatenilor regatului si a recrutilor aflati la antrenament.",al={"cui ii slujeste mcbride","loialitatea lui mcbride","din ce factiune face parte mcbride"}},b6028054={q="Ce isi doreste Marshal McBride?",a="McBride vrea sa asigure apararea Northshire Valley impotriva amenintarilor locale tot mai mari. Cu Stormwind Army intinsa la maximum, cauta sa mobilizeze noi recruti, paladini si voluntari care sa alunge kobolzii agresivi ce infesteaza valea si sa recucereasca Echo Ridge Mine.",al={"obiectivul lui McBride","ce incearca sa faca McBride","planurile lui McBride"}},cc66b2df={q="De ce se afla Marshal McBride aici?",a="McBride este stationat in afara Northshire Abbey, in calitate de comandant al garnizoanei militare din vale. Stormwind i-a incredintat mentinerea ordinii, organizarea apararii si instruirea noilor veniti inainte ca soldatii incercati sa fie trimisi in Elwynn Forest si mai departe.",al={"de ce se afla mcbride in northshire","postul lui mcbride","de ce se afla marshal mcbride la abatie"}},["307fdf7d"]={q="De cine este legat Marshal McBride?",a="McBride se afla in slujba inaltului comandament al Stormwind Army si se coordoneaza cu autoritatile locale din Elwynn, indrumandu-i in cele din urma pe luptatorii capabili catre Marshal Dughan din Goldshire. Lucreaza alaturi de clericii si instructorii manastirii pentru a pregati noi aparatori ai regatului.",al={"legaturile lui McBride","in fata cui raporteaza McBride","armata Stormwind a lui McBride"}}},fp="15,169,23.400.0,20.352.0,23.134.0,45.195.0,38.138.0,24.163.0,38.166.0,50.143.0"}
P.entries["npc:martie-jainrose"] = {n="Martie Jainrose",s="Martie Jainrose este botanista locala din Lakeshire si isi ingrijeste gradina de pe malul lui Lake Everstill, in Redridge Mountains. Pe langa cultivarea remediilor si florilor pentru orasul aflat la ananghie, se lupta cu fiarele salbatice care-i calca straturile si nutreste o afectiune tacuta pentru Guard Parker.",h="Martie Jainrose este botanista locala din Lakeshire si isi ingrijeste gradina de pe malul lui Lake Everstill...",kw={"bellygrub","narcise","guard parker","herbalist","lakeshire","martie jainrose","redridge"},ang={["faction:Alliance"]="Perseverenta lui Martie in Lakeshire reflecta rezilienta oamenilor din Redridge, care se straduiesc sa-si pastreze viata de zi cu zi chiar si atunci cand Stormwind lasa orasul in mare parte sa se descurce singur.",["profession:Herbalism"]="Pentru botanistii care calatoresc prin Redridge, Martie este o prezenta familiara, ingrijind flora delicata in ciuda atacurilor necrutatoare ale mistretilor salbatici si ale dusmanilor care se apropie."},sec={{t="O gradina langa lac",b="Martie Jainrose locuieste in Lakeshire si munceste cu sarguinta ca herbalista a asezarii. Chiar daca orcii Blackrock, gnollii si banditii locali ameninta regiunea, Martie se ocupa sa aprovizioneze orasul cu ierburi proaspete si aranjamente florale. Munca de zi cu zi ii este adesea intrerupta de fauna locala - mai ales de mistretul monstruos Bellygrub, care ii devasteaza frecvent straturile de gradina preferate. Dincolo de preocuparea pentru plante, Martie pare sa-l placa pe strajerul Parker, desi Parker o curteaza pe Darcy, care o considera pe Martie o rivala geloasa."}},faq={{q="Cine este Martie Jainrose?",a="Martie Jainrose este o botanista umana care locuieste in Lakeshire, in Redridge Mountains. Ingrijeste o gradina langa Lake Everstill, unde cultiva plante si pregateste leacuri din plante pentru localnici.",al={"Martie Jainrose","cine este Martie","herbalistul din Lakeshire"}},{q="Ce probleme are Martie cu fauna locala?",a="Un mistret salbatic urias si vestit pentru incapatanarea sa, pe nume Bellygrub, a inceput sa-i atace straturile de gradina, calcandu-i in picioare plantatiile delicate si mancandu-i ierburile inainte sa le poata culege.",al={"problema lui martie cu mistretii","gradina lui bellygrub","cine ii distruge gradina"}},{q="De cine este indragostita Martie in Lakeshire?",a="Se pare ca Martie il place pe Guard Parker, unul dintre paznicii orasului. Parker insa o curteaza pe Darcy, iar cand ii trimite un buchet de narcise de-ale lui Martie, ii cere sa nu-i spuna acesteia pentru cine este.",al={"martie indragostit","martie, paznicul lui parker","romantismul din Delivering Daffodils"}}},fx={["4d2b4277"]={q="De partea cui este Martie Jainrose?",a="Martie este o cetateana loiala a Alliance, care duce o viata linistita in Lakeshire. Desi nu lupta pe front si nu poarta arme, isi sustine orasul si aparatorii acestuia prin meseria ei de herbalist.",al={"factiunea lui martie jainrose","este martie din alliance"}},e745a8a7={q="Ce isi doreste Martie Jainrose?",a="Martie vrea sa-si ingrijeasca gradina in liniste si sa se ocupe de plantele medicinale fara sa fie deranjata. Necazul ei de capatai este un mistret urias pe nume Bellygrub, care ii calca in picioare pretioasele culturi, iar ea ii primeste cu bucurie pe toti calatorii dispusi sa alunge fiara.",al={"scopul lui martie jainrose","de ce are martie nevoie"}},["6d429f48"]={q="De ce se afla Martie Jainrose in Lakeshire?",a="Lakeshire este caminul lui Martie, unde isi castiga traiul cultivand ierburi si ingrijindu-si gradina pe malurile linistite ale Lake Everstill, in ciuda problemelor tot mai mari care framanta Redridge Mountains.",al={"de ce este Martie in Redridge","de ce este Martie Jainrose aici"}}},fp="15,293,20.545.0,23.202.0,54.182.0,35.199.0"}
P.entries["npc:marukai"] = {n="Marukai",s="Marukai este un troll al junglei Darkspear aflat la Zoram'gar Outpost, pe coasta invaluita in ceata din nord-vestul Ashenvale. Devotata apararii acestui cap de pod izolat al Horde, ea coordoneaza eforturile de a rari naga Wrathtail care se apropie si ameninta avanpostul.",h="Marukai este un troll al junglei Darkspear aflat la Zoram'gar Outpost, pe coasta invaluita in ceata din...",kw={"Ashenvale","Darkspear","troll de jungla","Marukai","naga","Wrathtail","Zoram Strand","Zoram'gar Outpost"},ang={["faction:Horde"]="Marukai sta la carma unuia dintre cele mai vulnerabile tabere de coasta ale Horde, in teritoriul night elf, bazandu-se pe campionii aliati pentru a impiedica naga localnici sa le cucereasca pozitia.",["race:Troll"]="Departe de ecourile calde din Sen'jin Village, Marukai intruchipeaza rezilienta tribului Darkspear, care isi croieste avanposturi fortificate pentru Horde prin tot Kalimdorul."},sec={{t="Apararea tarmului",b="Zoram'gar Outpost se afla izolat la capatul nordic al Zoram Strand, inconjurat de ruine antice, teritoriu ostil al elfilor noptii si o mare neastamparata. Pe masura ce naga Wrathtail ies cu forta din ape si din ruinele elfe stravechi pentru a cuceri tarmul, Marukai se straduieste sa impiedice tabara sa fie coplesita. Ea le porunceste campionilor Horde sa impinga oamenii-serpilor inapoi in valuri si sa le adune capetele, asigurandu-se ca avanpostul ramane o fortareata de coasta functionala."}},faq={{q="Cine este Marukai?",a="Marukai este un troll de jungla care le incredinteaza misiuni si apara Zoram'gar Outpost, tabara de coasta izolata a Horde-ului de pe tarmurile nord-vestice ale Ashenvale.",al={"povestea lui Marukai","cine este Marukai","npc Marukai"}},{q="De ce se lupta Marukai cu naga?",a="Naga Wrathtail au impanzit Zoram Strand si ruinele din apropiere. Pentru a asigura hotarele avanpostului si supravietuirea Horde pe coasta, Marukai angajeaza aventurieri sa le rareasca randurile vanandu-i direct.",al={"de ce sa omori naga","misiunea lui marukai cu naga","naga din zoram strand"}},{q="Unde se afla Marukai?",a="O poate gasi stand alaturi de cei din neamul ei la Zoram'gar Outpost, situat la varsarea Zoram Strand, in nord-vestul Ashenvale, chiar la sud de ruinele scufundate ale Blackfathom Deeps.",al={"unde se afla marukai","locatia lui marukai","gaseste-l pe marukai"}}},fx={["53dc13db"]={q="De partea cui este Marukai?",a="Marukai este loiala Horde. Avandu-si baza la Zoram'gar Outpost, pe coasta din Ashenvale, ea pazeste interesele Horde si se bizuie pe calatorii Horde pentru a apara asezarea de pericolele locale.",al={"factiunea lui Marukai","este Marukai de partea Horde","cui ii slujeste Marukai"}},["1bf5ddde"]={q="De ce se afla Marukai aici, la Zoram'gar Outpost?",a="Marukai este stationata la Zoram'gar Outpost pentru a apara capul de pod al Horde de pe Zoram Strand. Cum naga Wrathtail, agresivi, s-au intors pe plaje si ameninta granitele taberei, ea coordoneaza eforturile de securizare a perimetrului si de mentinere a sigurantei avanpostului.",al={"de ce se afla Marukai in Ashenvale","scopul lui Marukai","ce l-a adus pe Marukai aici"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Maestrul Apothecary Faranell"}
P.entries["npc:master-apothecary-lydon"] = {n="Apothecary Lydon",s="Apothecary Lydon este un cercetator morbid al Royal Apothecary Society, stationat in Tarren Mill. Cronic deprimat si extrem de plictisit, isi gaseste bucuria doar in perfectionarea amestecurilor letale si in privitul suferintei celor vii. Conduce cercetarile pentru crearea unor toxine noi si puternice, menite sa asigure controlul Forsaken asupra lui Hillsbrad si sa duca mai departe New Plague a lui Sylvanas.",h="Apothecary Lydon este un cercetator morbid al Royal Apothecary Society, stationat in Tarren Mill.",kw={"alchimist","elixir of agony","faranell","hillsbrad","lydon","royal apothecary society","tarren mill","umpi"},ang={["faction:Alliance"]="Pentru oamenii din Southshore, Lydon este un monstru ingrozitor care prepara boli letale si le testeaza fara discernamant pe fermieri si vietuitoare salbatice captive din Hillsbrad.",["profession:Herbalism"]="Atelierul lui Lydon este ticsit de reactivi, cazane si flora putrezita, demonstrand cum artele traditionale ale culesului sunt transformate in arme de Apothecary Society.",["race:Undead"]="Lydon intruchipeaza misiunea aparte a Royal Apothecary Society: dezvoltarea New Plague pentru a le asigura un viitor celor din Forsaken si pentru a-i eradica pe cei vii."},sec={{t="Pustnicul din Tarren Mill",b="Aflat in capela transformata in laborator din Tarren Mill, Apothecary Lydon intruchipeaza firea rece si calculata a Royal Apothecary Society. Este cuprins de o melancolie profunda si apatica, dezgustat de florile inflorite si aerul proaspat din Hillsbrad Foothills. Singura indeletnicire care-i alunga tristetea fara sfarsit este arta mortii. Cand nu-l supravegheaza nimeni, isi omoara vremea otravindu-si, disecandu-si si readucandu-si la viata bietul broscoi Umpi, asteptand mereu sa soseasca noi reagenti."},{t="Amestecuri ale agoniei",b="Colaborand cu Master Apothecary Faranell in Undercity, Lydon desfasoara experimente amanuntite pe teren, prin Hillsbrad. Cercetarile sale avanseaza de la Elixir of Suffering la virulentul Elixir of Agony. Pentru a le verifica eficienta, Lydon trimite aventurieri sa testeze potiuni pe tinte locale, de la animale salbatice nevinovate si vietati domesticite pana la fermieri umani capturati. Loialitatea sa ii apartine in intregime Dark Lady, iar el tanjeste dupa ziua in care New Plague, odata desavarsita, va curata lumea celor vii."},{t="Veninul loa",b="Pe langa preparatele sale obisnuite, curiozitatea intelectuala a lui Lydon se extinde si la otravurile ezoterice. Cand in regiune apar sticle cu venin misterios, el se consulta cu mistici troli precum Master Gadrin, pentru a le afla originea. Cercetarea descopera o urma care duce direct la zeita-paianjen Shadra, in Hinterlands. Odata obtinut, acest venin stravechi este trimis direct la Apothecarium, in Undercity, pentru a sprijini mai departe programul Forsaken de creare a plagilor."}},faq={{q="Cine este Apothecary Lydon?",a="Este un alchimist al Royal Apothecary Society, care isi desfasoara activitatea din Tarren Mill, in Hillsbrad Foothills. Supravegheaza dezvoltarea unor plagi si toxine experimentale in numele lui Lady Sylvanas Windrunner.",al={"cine este lydon","lydon tarren mill","povestea lui apothecary lydon"}},{q="De ce este Lydon atat de abatut?",a="Lydon sufera de o melancolie profunda si considera respingatoare frumusetea naturala si aerul curat din Hillsbrad. Singurele lucruri care ii ridica moralul sunt experimentele crude, suferinta celor vii si mirosul fluidelor alchimice de imbalsamare.",al={"de ce e trist","depresia lui lydon","de ce e lydon posomorat"}},{q="Cine este Umpi?",a="Umpi este o broasca pe care Lydon o tine in atelierul sau si pe care o numeste cu ironie asistenta lui. In realitate, isi alina plictiseala extrema otravind, omorand si readucand la viata in mod repetat amfibianul neajutorat.",al={"lydon broasca","cine este broasca","povestea lui umpi"}},{q="Ce este Elixir of Agony?",a="Este o otrava experimentala puternica, pe care Lydon o prepara din flori Mudsnout Blossom, rafinata cu coloidul de descompunere al lui Master Apothecary Faranell si activata cu o potiune puternica din sange de troll, solzi Daggerspine si ochi smulsi de pesti. Apoi o amesteca intr-un butoi de bere neagra furata de la piticii din Dun Garok si o testeaza pe fermieri captivi din Hillsbrad.",al={"misiunea Elixir of Agony","ce este Elixir of Agony","elixirul lui Lydon"}},{q="Cum a devenit Lydon Forsaken?",a="Nu exista marturii despre cum a murit sau a revenit la viata Lydon. Ca si ceilalti Forsaken, s-a eliberat de sub controlul Lich King-ului sub conducerea Sylvanas, iar acum isi dedica existenta de strigoi lui Dark Lady si New Plague.",al={"trecutul lui lydon","era lydon om","lydon in al treilea razboi"}},{q="Ce trimite Lydon in Undercity?",a="Dupa ce descopera vase stravechi cu venin in Hinterlands si coordoneaza caderea zeului-paianjen troll Shadra, Lydon ii colecteaza veninul divin concentrat si il trimite direct la Master Apothecary Faranell, pentru a intari cercetarile Societatii asupra plagilor.",al={"lydon undercity venin","shadra venin misiune"}}},fx={["4ad88718"]={q="De partea cui este Apothecary Lydon?",a="Apothecary Lydon este neclintit de loial fata de Lady Sylvanas Windrunner, de Forsaken si de Horde. Este un cercetator de rang inalt in Royal Apothecary Society, primind indrumari directe de la Master Apothecary Faranell din Undercity. Tot ce prepara serveste planurilor marete ale Sylvanas, menite sa asigure tinutul pentru strigoi.",al={"factiunea lui lydon","pe cine slujeste lydon","este lydon forsaken"}},["64f2c0db"]={q="Ce isi doreste Apothecary Lydon?",a="Lydon este absorbit de crearea si perfectionarea New Plague pentru Dark Lady. Cauta toxine puternice, sange de pradator si veninuri letale din intreaga regiune pentru a-si rafina licorile, printre care Elixir of Suffering si Elixir of Agony, cu scopul de a aduce suferinta si moarte celor vii.",al={"ce incearca sa faca lydon","scopul lui lydon","de ce vrea lydon otravuri"}},["26e1a5a5"]={q="De ce se afla Apothecary Lydon in Tarren Mill?",a="Lydon este stationat in laboratorul de alchimie din Tarren Mill pentru a aduna reactivi din regiune si a testa formule alchimice letale aproape de teritoriul inamic. Hillsbrad Foothills ofera terenuri fertile de incercare impotriva faunei locale, a incursiunilor ostile ale piticilor si a orasului omenesc Southshore, aflat ceva mai jos pe drum.",al={"de ce se afla Lydon in Hillsbrad","scopul lui Lydon in Tarren Mill","de ce se afla Apothecary Lydon aici"}},["19c08bcd"]={q="De cine este legat Apothecary Lydon?",a="Lydon raspunde direct in fata lui Master Apothecary Faranell si a Royal Apothecary Society. Colaboreaza cu colegi din tot Azeroth, ajutand-o pe Apothecary Zamah din Thunder Bluff sa prepare o toxina pentru a rezolva problemele Horde in Stonetalon Mountains si coordonand cercetari cu alti apotecari Forsaken raspanditi prin Lordaeron.",al={"legaturile lui Lydon","cine lucreaza cu Lydon","aliatii lui Lydon"}}},fp="16,354,26.508.0,20.517.1,16.465.1,24.213.0,26.245.0,12.207.0,28.337.1,30.208.0,38.260.1"}
P.entries["npc:master-gadrin"] = {n="Master Gadrin"}
P.entries["npc:master-vornal"] = {n="Master Vornal"}
P.entries["npc:mastok-wrilehiss"] = {n="Mastok Wrilehiss",s="Mastok Wrilehiss este un ofiter orc stationat la Splintertree Post, in estul Ashenvale. In calitate de coordonator defensiv esential al Horde in padurea disputata, el le da ordine cercetasilor si razboinicilor sa securizeze granitele din apropiere si sa infrunte amenintarile elementale corupatoare. Prezenta sa este vitala pentru mentinerea fragilei pozitii pe care Horde o pastreaza in fata ostilitatii neincetate a elfilor noptii.",h="Mastok Wrilehiss este un ofiter orc stationat la Splintertree Post, in estul Ashenvale.",kw={"Ashenvale","Earthen Ring","Mastok","Orc","Splintertree","Stonetalon","Wrilehiss"},ang={["class:Shaman"]="Ingrijorarea lui Mastok cu privire la elementalii corupti din padure ii indruma adesea pe aventurieri sa ceara sfatul Earthen Ring din Zoram'gar Strand.",["faction:Alliance"]="Mastok Wrilehiss reprezinta prezenta militara orceasca bine inradacinata in Ashenvale, aparand asezarea fortificata Splintertree impotriva santinelelor Night Elf.",["faction:Horde"]="Pentru campionii Horde care lupta sa pastreze un cap de pod la frontiera din Ashenvale, Mastok este un comandant important, capabil sa te indrume spre sarcini esentiale in intreaga regiune."},sec={{t="Un Bulwark in padurile stravechi",b="Splintertree Post se afla adanc in umbra coronamentului falnic din Ashenvale, complet inconjurat de tinuturi ostile ale elfilor noptii. Mastok Wrilehiss este unul dintre aparatorii de baza ai avanpostului si supravegheaza rutele de aprovizionare si activitatea din padure. Pozitia este primejdioasa: orice semn de slabiciune atrage atacuri fulgeratoare din partea Sentinels, care vad asezarea drept o intruziune ce pangareste tinutul."},{t="Coordonarea frontului",b="Din pozitia sa din incinta palisadei, Mastok le incredinteaza in mod activ aventurierilor aflati in trecere sarcini strategice esentiale. Supravegheaza cu atentie granitele care duc spre tinuturi invecinate, precum Stonetalon Mountains, si trimite cercetasi sa se consulte cu shaman precum Je'neu Sancrea, din Earthen Ring, aflat in Zoram'gar Strand. Indatoririle sale imbina apararea militara cu supravegherea fortelor stranii si corupatoare care napastuiesc elementalii locali."}},faq={{q="Cine este Mastok Wrilehiss?",a="Mastok Wrilehiss este un Orc de elita stationat la Splintertree Post, in Ashenvale. Actioneaza ca ofiter si ca personaj care ofera misiuni, avand sarcina sa apere avanpostul impotriva incursiunilor elfilor noptii si sa cerceteze amenintarile regionale din apropiere.",al={"cine este Mastok","rolul lui Mastok Wrilehiss","cine este acest orc"}},{q="Unde poate fi gasit Mastok Wrilehiss?",a="Se afla in Splintertree Post, un avanpost fortificat al Horde din estul-centrul Ashenvale, de-a lungul drumului principal prin padure.",al={"locatia lui mastok","unde este mastok wrilehiss","harta lui mastok"}},{q="Ce sarcini le da Mastok aventurierilor?",a="Mastok le incredinteaza aventurierilor Horde sarcini strategice, printre care cercetarea amenintarilor elementale corupte din padure, securizarea trecatorilor catre Stonetalon si trimiterea solilor la Je'neu Sancrea din Earthen Ring.",al={"misiunile lui Mastok","misiuni de la Mastok"}},{q="De ce este Splintertree Post supus unei presiuni constante?",a="Avanpostul serveste drept centru principal de taiere a lemnului si fortareata a Horde in Ashenvale. Elfii noptii bastinasi considera prezenta orcilor si exploatarea lemnului lor o profanare grava a tinuturilor sacre, ceea ce duce la ciocniri neintrerupte.",al={"de ce ataca Night Elves Splintertree","conflictul de la Splintertree Post"}},{q="De ce ii trimite Mastok pe calatori la Je'neu Sancrea?",a="Samanii Earthen Ring, inclusiv Je'neu de la Zoram'gar Strand, studiaza si vindeca instabilitatea elementala care bantuie Ashenvale. Mastok ii pune pe luptatorii din prima linie in legatura cu experienta lor spirituala, pentru a se ocupa de elementalii de apa corupti si de tulburarile neobisnuite.",al={"de ce sa contactezi Cercul Pamantului","mastok si jeneu"}},{q="Este Mastok Wrilehiss ostil jucatorilor din Alliance?",a="Da. Mastok este un membru devotat al Horde si un aparator de elita al Splintertree Post, asa ca va ataca pe loc jucatorii Alliance care se apropie de tabara.",al={"poate Alliance vorbi cu mastok","poate fi ucis mastok"}}},fx={["414a3ea9"]={q="De ce se afla Mastok Wrilehiss in Ashenvale?",a="Mastok Wrilehiss este detasat la Splintertree Post pentru a ajuta la securizarea avanpostului Horde din padurile disputate ale Ashenvale. Aparator cu experienta in randurile fortelor Warsong, el supravegheaza apararea locala, urmareste tulburarile care afecteaza tinuturile salbatice din jur si recruteaza calatori capabili sa infrunte amenintarile elementale corupatoare si ostilitatea elfilor noptii din apropiere.",al={"de ce este Mastok aici","Mastok Wrilehiss la Splintertree Post","de ce este Mastok la Splintertree"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Mathias Shaw",s="In Old Town, Mathias Shaw conduce SI:7, agentia secreta de informatii a Stormwind. Din umbra, trimite spioni si cercetasi sa apere regatul de conspiratiile din interior si de ororile de dincolo.",h="In Old Town, Mathias Shaw conduce SI:7, agentia secreta de informatii a Stormwind.",kw={"asasin","Blightcaller","Kearnen","Mathias Shaw","Old Town","SI:7","spymaster","Stormwind","VanCleef"},ang={["class:Rogue"]="Ca Rogue, il poti lua drept model pe Mathias Shaw, un maestru al artei Rogue human. Rogues din Alliance sunt adesea trimisi la el pentru misiuni tactice avansate si otravuri de specialitate.",["faction:Alliance"]="Ca membru al Alliance, te poti bizui pe Shaw sa stranga informatii militare pentru Highlord Bolvar Fordragon si regele-copil Anduin. Spionii sai pazesc regatul de subversiuni.",["race:Human"]="Ca Human, poti vedea revolta Defias Brotherhood ca parte a dezbinarii amare din Kingdom of Stormwind de dupa reconstructia sa."},sec={{t="Maestrul SI:7",b="Mathias Shaw conduce spionii si asasinii din Stormwind de la sediul secret al SI:7, ascuns in spatele cazarmei din Old Town. Reteaua sa clandestina se intinde in Eastern Kingdoms si dincolo de ele. Loial fata de House of Wrynn, Shaw cantareste cu grija fiecare amenintare. Se increde in pumnale nevazute si mesaje furate pentru a apara Stormwind la fel de mult ca in armura si gardienii palatului."},{t="Umbra lui VanCleef",b="Mathias Shaw il considera candva pe Edwin VanCleef prieten din copilarie. Shaw l-a instruit pe VanCleef in arta furisarii si a asasinatului, sperand ca pietrarul talentat va sluji regatului alaturi de el. Dar, dupa ce Stonemasons Guild a fost alungata in urma reconstructiei Stormwind, VanCleef a folosit acele lectii impotriva coroanei. Acum, Shaw coordoneaza supravegherea si infiltrarea in tot Westfall, ca sa infranga rebeliunea vechiului sau prieten."},{t="Ochi asupra regatelor",b="Mathias Shaw urmareste amenintarile de dincolo de tulburarile din Westfall si Elwynn. Rapoartele despre operatiuni Forsaken neobisnuite din Eastern Plaguelands l-au determinat sa trimita cinci dintre cei mai buni agenti ai sai sa investigheze. Doar unul s-a intors viu, bolborosind despre \"Nathanos\" si un \"Blightcaller\" inainte sa moara in somn. Shaw se bazeaza acum pe campioni de incredere care sa mearga acolo unde dispar cercetasii sai si sa descopere pericolele ce se aduna la granitele regatului."}},faq={{q="Cine este Mathias Shaw?",a="Mathias Shaw conduce SI:7, serviciul de informatii si breasla asasinilor din Stormwind. Din Old Town, el coordoneaza spionii regatului si apararea secreta, sub autoritatea tronului.",al={"cine este Shaw","liderul SI:7","povestea lui Mathias Shaw","spion-maestrul din Stormwind"}},{q="Unde poate fi gasit Mathias Shaw?",a="Il poti gasi pe Mathias Shaw in sediul SI:7 din Old Town, Stormwind City, in spatele cazarmelor militare.",al={"locatia lui Shaw","unde este Mathias Shaw","gaseste-l pe Mathias Shaw"}},{q="Ce legatura are cu Edwin VanCleef?",a="Legatura lui Shaw cu Edwin VanCleef este unul dintre secretele Westfallului. El consemneaza intr-un raport pentru Gryan Stoutmantle informatiile SI:7 despre Stonemasons Guild. Urmareste Defias Brotherhood pana la capat ca sa afli cat de strans sunt legate.",al={"Shaw si VanCleef","prietenul lui VanCleef","Mathias si Edwin"}},{q="Ce inseamna SI:7?",a="SI:7 este principala organizatie de informatii din Stormwind. Agentii sai aduna informatii, desfasoara activitati de spionaj si duc la indeplinire asasinate secrete pentru a proteja regatul si interesele Alliance.",al={"ce este SI:7","ce inseamna SI:7","serviciile de informatii din Stormwind"}},{q="De ce il intereseaza pe Mathias Shaw Westfall?",a="Shaw este interesat de Westfall fiindca acolo se afla fortareata Defias Brotherhood. Isi mentine agenti acolo pentru a-i supraveghea pe rebeli si a le zadarnici planurile impotriva Stormwind.",al={"shaw in westfall","si7 in westfall","klaven's tower"}},{q="Ce s-a intamplat cu agentii pe care i-a trimis Shaw in Plaguelands?",a="Shaw a trimis cinci agenti sa investigheze miscarile suspecte ale Forsaken in Eastern Plaguelands. Patru nu s-au mai intors. Singurul supravietuitor a bolborosit despre \"Nathanos\" si un \"Blightcaller\", apoi a murit in somn cateva zile mai tarziu.",al={"misiunea lui Shaw in Plaguelands","cei cinci cercetasi Shaw","cercetasii din Marris Stead"}}},fx={ad27d291={q="De partea cui este Mathias Shaw?",a="Maestrul Mathias Shaw slujeste cu o loialitate de nezdruncinat Alliance, Casei Wrynn si Kingdom of Stormwind. In calitate de conducator al serviciului de informatii al regatului, fiecare misiune secreta pe care o supravegheaza si fiecare spion pe care il coordoneaza au drept scop apararea Stormwindului de subversiuni interne si amenintari straine.",al={"factiunea lui mathias shaw","pe cine slujeste shaw","este mathias shaw loial"}},["14719004"]={q="Ce doreste Mathias Shaw?",a="Principala preocupare a lui Shaw este eliminarea amenintarilor existentiale la adresa Stormwind inainte sa loveasca. El coordoneaza reteaua secreta SI:7 pentru a zadarnici comploturile Defias Brotherhood, a supraveghea miscarile primejdioase ale Forsaken din nord si a strange informatiile necesare pentru a apara regatul intr-o perioada de profunda vulnerabilitate politica.",al={"scopul lui mathias shaw","ce vrea shaw","motivele lui shaw"}},a0b783f7={q="De ce este Mathias Shaw renumit sau temut?",a="Shaw este cunoscut in tot regatul drept maestrul spionilor si al asasinilor. Renumit pentru maiestria suprema in furisare, infiltrare si ucidere fara zgomot, reteaua sa vasta de informatii face ca putine lucruri sa se petreaca in regat fara stirea lui - sau fara interventia lamelor sale.",al={"de ce este mathias shaw faimos","de ce se tem de shaw","maestrul asasinilor"}}},fp="12,190,14.348.0,18.407.1,24.422.0,20.176.0,32.112.0,41.234.0,25.187.0,43.166.0,57.217.0"}
P.entries["npc:mathredis-firestar"] = {n="Mathredis Firestar",s="Mathredis Firestar este un mag elf de sange excentric, care locuieste la Flame Crest, in Burning Steppes. El faureste descantece puternice numite Lesser Arcanums, folosind cercetarile arcane ale maestrului sau decedat. In acest fel, se hraneste cu energiile reziduale eliberate in timpul procesului de legare, pentru a-si tine in frau dependenta de magie.",h="Mathredis Firestar este un mag elf de sange excentric, care locuieste la Flame Crest, in Burning Steppes.",kw={"arcanum","Burning Steppes","dreamseeker","firestar","Flame Crest","libram","mathredis","telmius"},ang={["class:Mage"]="Magii vor recunoaste sinteza arcana a lui Mathredis ca pe o metoda disperata si instabila de a extrage hrana magica bruta din procesul de legare a obiectelor."},sec={{t="Mostenirea unui maestru si dependenta de magie",b="Mathredis Firestar a invatat mestesugul crearii arcanumurilor - nestemate concentrate cu putere arcana - de la mentorul sau, Telmius Dreamseeker. Telmius a avut un sfarsit sumbru in ruinele stravechi din Dire Maul, incercand sa smulga secrete magice de la Shen'dralar. Desi Telmius a inventat aceste legaturi magice, Mathredis nu are maiestria necesara pentru a le crea pe cele mai puternice. In schimb, se specializeaza in Lesser Arcanums. Pentru Mathredis, aceasta munca este mult mai mult decat un exercitiu academic: asemenea tuturor elfilor de sange de dupa caderea Sunwell, sufera de o foame mistuitoare de putere arcana. Legarea materialelor de libramuri stravechi dezlantuie descarcari violente de energie magica, pe care Mathredis le absoarbe pentru a se sustine."},{t="Arta Arcanumului",b="Aventurierii care ii aduc lui Mathredis tomurile potrivite - precum Librams of Constitution, Resilience, Rumination, Tenacity sau Voracity - impreuna cu reactivi rari, il vor gasi dornic sa-si puna mestesugul in slujba lor. Procesul leaga reactivii magici instabili direct de text, concentrandu-le esenta intr-un arcanum care poate fermeca pentru totdeauna coifurile sau armurile pentru picioare. Atat timp cat aventurierii furnizeaza componentele, Mathredis primeste plata si hrana arcana ambientala de care tanjeste cu disperare."}},faq={{q="Cine este Mathredis Firestar?",a="Mathredis Firestar este un mag elf de sange stationat la avanpostul neutru Flame Crest, in Burning Steppes. Este un arcanist capabil sa faureasca Arcanum-uri inferioare pentru a vraji armuri.",al={"povestea lui Mathredis","cine este Mathredis Firestar","Firestar, elf de sange"}},{q="De ce creeaza Mathredis arcanumuri?",a="Dupa distrugerea Sunwell, elfi de sange sufera de o sevraj magic sever. Mathredis se hraneste cu energiile magice brute, reziduale, eliberate in timpul crearii si legarii arcanumurilor, pentru a-si alina dependenta rasiala.",al={"de ce sa creezi arcanumuri","motivul lui mathredis","de ce sa creezi libramuri"}},{q="Cine a fost Telmius Dreamseeker?",a="Telmius Dreamseeker a fost raposatul maestru al lui Mathredis si inventatorul initial al arcanumurilor. Telmius a pornit spre ruinele din Dire Maul pentru a dobandi cunostinte de la Shen'dralar, dar a fost ucis acolo inainte sa-si poata transmite intreaga experienta.",al={"telmius","maestrul lui Mathredis","cine era maestrul lui"}},{q="Ce feluri de arcanum poate crea Mathredis?",a="Mathredis poate fauri Arcanum-uri Inferioare ale Constitutiei, Rezistentei, Cugetarii, Tenacitatii si Lacomiei. Arcanum-urile cele mai puternice erau cunoscute doar de maestrul sau, Telmius, si continua sa-i depaseasca puterile.",al={"care arcanum","arcanum inferior","lista de libramuri"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="Mathrengyl Bearwalker"}
P.entries["npc:maur-grimtotem"] = {n="Maur Grimtotem"}
P.entries["npc:maur-raincaller"] = {n="Maur Raincheller"}
P.entries["npc:maurin-bonesplitter"] = {n="Maurin Bonesplitter",s="Maurin Bonesplitter este un invatat si vrajitor Forsaken, stationat la Ghost Walker Post din Desolace. Numit de Keldran sa supravegheze activitatea cultelor demonice, isi foloseste cunoasterea profunda a intelepciunii stravechi pentru a distruge Burning Blade. Maurin ii priveste pe adeptii cultului cu un dispret absolut, considerandu-i niste nebuni care nu vad entitatile intunecate ce ii trag de sfori.",h="Maurin Bonesplitter este un invatat si vrajitor Forsaken, stationat la Ghost Walker Post din Desolace.",kw={"burning blade","corupator","desolace","forsaken","ghost walker post","keldran","maurin bonesplitter"},ang={["class:Mage"]="Mage care viziteaza Ghost Walker Post il pot aprecia pe Maurin pentru felul sau cumpatat si intelectual de a descalci ritualurile intunecate cu contramasuri specializate.",["class:Warlock"]="Warlocks vor recunoaste intelegerea profunda a lui Maurin asupra pactelor demonice, desi dispretul lui aminteste cu asprime de primejdia pe care o presupune slujirea demonilor puternici.",["faction:Horde"]="Maurin intruchipeaza sprijinul specializat pe care Undercity il ofera avanposturilor vestice ale Horde, aducand cunostinte academice intunecate pentru a-si ajuta aliatii tauren impotriva coruperii demonice.",["race:Undead"]="Maurin demonstreaza ca puterea celor din Forsaken depinde la fel de mult de cercetarea arcana iscusita si exploatarea slabiciunilor dusmanului, precum de forta necromantica bruta."},sec={{t="Un invatat printre proscrisi",b="Desi Ghost Walker Post este in principal un avanpost tauren si Horde in mijlocul tinuturilor aride din Desolace, Maurin Bonesplitter se remarca drept unul dintre putinii sai locuitori Forsaken. Departe de a fi un soldat brutal, Maurin este un vrajitor erudit, cu vaste cunostinte despre istorii interzise si forte oculte. Talentul sau arcane si inteligenta ascutita i-au atras atentia lui Keldran, care l-a trimis in regiune sa observe prezenta demonica in crestere si sa coordoneze atacuri tintite impotriva ei."},{t="Dispretul fata de Burning Blade",b="Maurin isi indreapta cea mai mare parte a rautatii impotriva cultului Burning Blade, instalat in Desolace. Ii dispretuieste profund ambitia nesabuita si ii ia in ras pe sectanti pentru ca nu inteleg ca puterea imprumutata doar ii leaga ca slugi de stapanii lor demoni. Folosindu-se de vraji de clarviziune si de cunostinte ritualice, Maurin ii recruteaza pe aventurierii Horde pentru a sabota metodic invocarile cultului si a-i submina operatiunile prin tinutul pustiu."}},faq={{q="Cine este Maurin Bonesplitter?",a="Maurin Bonesplitter este un vraci Forsaken si invatat care locuieste la Ghost Walker Post, in Desolace. Numit de Keldran, isi foloseste cunostintele despre traditiile stravechi si magia intunecata pentru a starpi cultul Burning Blade, activ in regiune.",al={"povestea lui Maurin Bonesplitter","cine este Maurin","Maurin din Desolace"}},{q="De ce sta un strigoi la un avanpost tauren?",a="Ghost Walker Post este o asezare importanta a Horde in Desolace. Keldran l-a stationat acolo pe Maurin tocmai fiindca avanpostul este un loc ideal de unde pot fi observati si combatuti cultistii Burning Blade care infesteaza tinuturile salbatice din jur.",al={"de ce este Maurin la Ghost Walker Post","Forsaken in Desolace"}},{q="Ce parere are Maurin despre Burning Blade?",a="Maurin priveste Burning Blade cu un dispret profund. Ii considera pioni jalnici si ignoranti, care se amagesc crezand ca detin puterea adevarata, fara sa inteleaga ca sunt doar marionetele unor stapani demonici.",al={"Mauri si Burning Blade","de ce uraste Maurin Burning Blade"}},{q="Cine l-a trimis pe Maurin Bonesplitter in Desolace?",a="Keldran l-a numit pe Maurin in aceasta functie in Desolace. Recunoscand cunostintele vaste ale lui Maurin despre practicile cultelor si intelepciunea straveche, Keldran i-a cerut sa impiedice activitatea Burning Blade in zona si, in cele din urma, sa-i elimine.",al={"cine l-a trimis pe maurin","maurin keldran","seful lui maurin"}},{q="Ce fel de sarcini le da Maurin aventurierilor?",a="Maurin le cere aventurierilor sa investigheze Burning Blade si sa adune un scalp de Hatefury Shadowstalker si un cristal oracular naga. Foloseste aceste ingrediente pentru a infrange protectiile de clarviziune si a-l localiza pe lordul demon din spatele cultului.",al={"misiunile lui maurin","ce doreste maurin"}},{q="Este Maurin afiliat la Cenarion Circle sau la Horde?",a="Maurin este un membru loial al Forsaken si slujeste Horde. Isi desfasoara activitatea exclusiv din tabara Horde de la Ghost Walker Post, ajutandu-i pe campionii Horde sa curete tinuturile pustii de activitatea cultistilor.",al={"este maurin de partea Horde","fractia lui maurin"}}},fp="19,361,24.495.0,30.459.0,27.231.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="Maxan Anvol",s="La Distileria Thunderbrew din Kharanos, Maxan Anvol antreneaza preoti pitici in Lumina Sfanta. El ii testeaza pe tinerii acoliti inainte ca acestia sa castige vesmintele Bisericii.",h="La Distileria Thunderbrew din Kharanos, Maxan Anvol antreneaza preoti pitici in Lumina Sfanta.",kw={"desperate prayer","dun morogh","garments of the light","lumina sacra","kharanos","maxan anvol","instructor de preoti","thunderbrew distillery"},ang={["class:Priest"]="Ca preot, Maxan Anvol te ghideaza devreme in Dun Morogh si deschide calea catre disciplina sfanta fundamentala. El invata rugaciuni rasiale, cum ar fi Rugaciunea disperata si iti acorda primele haine de biserica.",["faction:Alliance"]="In calitate de membru al Aliantei, il gasesti pe Maxan care are grija de pregatirea fizica si spirituala a alpinistilor si cercetasilor care il pazesc pe Dun Morogh de trogg, trolii de inghet si fiarele salbatice.",["race:Dwarf"]="Ca pitic, vezi credinta practica a Ironforge, unde oamenii se aduna, langa butoaiele de bere ale lui Kharanos."},sec={{t="Un preot in carciuma",b="Maxan Anvol se ocupa de bunastarea spirituala a catunului de la Distileria Thunderbrew, unde se aduna calatori, alpinisti si acoliti. Kharanos se afla intre Coldridge Valley si Ironforge, iar hanul sau ii atrage pe cei care trec prin ele. Maxan ofera rugaciuni si sfaturi oricui intra, cu halbe de stout la indemana."},{t="Punerea la incercare a credinciosilor",b="Maxan Anvol ii testeaza pe preoti incepatori inainte ca acestia sa se aventureze in lumea larga. El a facut ca initiatii sa foloseasca rugaciuni de baza de vindecare asupra aparatorilor raniti ai lui Dun Morogh. Cei care dau dovada de devotament si pricepere primesc primele vesminte preotesti, marcand locul lor recunoscut in Biserica Sfintei Lumini."}},faq={{q="Unde il pot gasi pe Maxan Anvol?",a="Maxan Anvol poate fi gasit in interiorul Distilleriei Thunderbrew din Kharanos, hanul orasului si locul de adunare din Dun Morogh.",al={"locatia lui Maxan Anvol","unde este Maxan","antrenor de Priest in Kharanos"}},{q="Ce preda Maxan Anvol?",a="Maxan Anvol ii invata pe preoti incepatori si calfe vraji de vindecare sfanta, control al umbrelor si protectie divina. De asemenea, ii invata pe preoti pitici rugaciuni, cum ar fi Rugaciunea disperata.",al={"ce antreneaza","vraji maxan anvol"}},{q="De ce isi petrece un preot sfant timpul intr-o distilerie?",a="Viata si sarbatoarea piticilor se aduna in jurul fabricii de bere si a tavernelor. Distileria Thunderbrew este locul de adunare publica al lui Kharanos si un loc de odihna pentru calatori, astfel incat Maxan poate oferi confort spiritual orasenilor, gardienilor si trecatorilor.",al={"de ce distilerie","preot intr-un bar"}},{q="Ofera Maxan Anvol sarcini speciale?",a="Da. Maxan Anvol ii testeaza pe aspirantii preoti cu incercari precum „In favoarea luminii” si „Hainele luminii”. El ii trimite sa vindece alpinistii raniti in zapada, iar cei care reusesc isi castiga hainele de acolit.",al={"misiunile lui Maxan","Garments of the Light"}},{q="Ce le spune?",a="Maxan Anvol ii avertizeaza pe aventurieri sa nu intoarca niciodata spatele la Lumina Sfanta. Harul divin poate fi ceea ce le salveaza vietile in lupta.",al={"replici maxan","citat maxan"}},{q="Pot gnomii sa invete de la Maxan Anvol?",a="Da. Gnomii se pot antrena ca preoti, iar Maxan saluta orice membru al Aliantei care s-a angajat la Lumina.",al={"pot gnomii sa vorbeasca cu el","antrenor de Priest pentru gnomi"}}},fx={["32034ea0"]={q="Cine este Maxan Anvol?",a="Maxan Anvol este un preot al Holy Light, aflat in Kharanos. El este instructor pentru credinciosii incepatori din Dun Morogh, punandu-i la incercare pe tinerii acoliti in privinta disciplinei si a comuniunii cu Light, inainte de a le darui vesminte potrivite rangului lor in biserica.",al={"cine este Maxan","povestea lui Maxan Anvol","antrenor Priest in Kharanos"}},["310c3ecc"]={q="De partea cui este Maxan Anvol?",a="El ramane loial Kingdom of Ironforge, Holy Light si Grand Alliance. Isi dedica slujirea ocrotirii localnicilor din Dun Morogh si pregatirii noilor preoti sa sustina credinta pe intregul teritoriu al Alliance.",al={"factiunea lui Maxan","este Maxan din Alliance","loialitatea lui Maxan Anvol"}},["1141108e"]={q="Ce vrea Maxan Anvol?",a="Maxan vrea sa cultive devotamentul fata de Holy Light si sa se asigure ca preotii novici sunt bine pregatiti pentru incercarile lumii. Ii pune la incercare pe aspiranti ca sa vada daca sunt vrednici de vesmintele lor sacre si le aminteste tuturor trecatorilor sa nu abandoneze niciodata harul Luminii.",al={"scopul lui Maxan Anvol","ce vrea Maxan","motivul lui Maxan Anvol"}}},fp="11,163,19.324.0,20.292.0,29.123.0,28.178.0,49.229.0,41.216.0,32.128.0,34.109.0"}
P.entries["npc:maybell-maclure"] = {n="Maybell Maclure",s="La Maclure Vineyards, in Elwynn Forest, Maybell Maclure iubeste in taina pe cineva din familia Stonefield. Vrajba amara dintre familia ei si Stonefields, vecinii lor, o tine departe de Tommy Joe Stonefield.",h="La Maclure Vineyards, in Elwynn Forest, Maybell Maclure iubeste in taina pe cineva din familia Stonefield.",kw={"indragostiti","Maclure","Maybell","Stonefield","Tommy Joe","podgorii"},ang={["faction:Alliance"]="Pentru calatorii Alliance care strabat Elwynn Forest, povestea de dragoste a lui Maybell arata ca necazurile personale si vechile ranchiune dainuie in inima regatului."},sec={{t="Indragostiti sub un semn potrivnic in vii",b="Maybell Maclure lucreaza la viile familiei, sub umbra vechii dusmanii cu Stonefields de alaturi. S-a indragostit de Tommy Joe Stonefield, mostenitorul fermei rivale. Rudele lor ii tin despartiti, iar Maybell cauta o modalitate de a vorbi cu el fara sa fie vazuta de familia ei vigilenta."},{t="O licoare pentru iubirea adevarata",b="Nefiind in stare sa traverseze pe fata zona dintre ferme, Maybell cere ajutorul calatorilor binevoitori si al lui Gramma Stonefield. William Pestle, alchimistul din Goldshire, prepara o licoare a invizibilitatii. Maybell o bea ca sa se strecoare nevazuta de la gospodaria Maclure si sa se intalneasca cu Tommy Joe pe malul raului."}},faq={{q="De ce nu se pot vedea Maybell si Tommy Joe?",a="Familiile Maclure si Stonefield se afla de ani buni intr-o rivalitate inversunata. Ambele interzic orice legatura intre casele lor, asa ca Maybell si Tommy Joe isi ascund povestea de dragoste de rude.",al={"de ce exista o cearta intre familii","cearta dintre maclure si stonefield","de ce nu pot fi impreuna"}},{q="Ce o impiedica pe Maybell sa plece din vie?",a="Familia lui Maybell o supravegheaza indeaproape din cauza vrajbei cu Stonefields. Are nevoie de ajutor ca sa se intalneasca cu Tommy Joe fara sa le atraga atentia.",al={"cum reuseste maybell sa iasa pe furis","potiune de invizibilitate elwynn","cum il intalneste pe tommy"}},{q="Unde se intalneste Maybell cu Tommy Joe?",a="Tommy Joe asteapta pe malul raului, la granita dintre Maclure Vineyards si Stonefield Farm, ferit de privirile directe dinspre ambele gospodarii.",al={"locul intalnirii","unde se intalnesc","unde este Tommy Joe"}},{q="Cine o ajuta pe Maybell cu povestea ei de dragoste?",a="Gramma Stonefield ii intelege pe indragostiti si ii indruma pe calatorii dispusi sa ajute la William Pestle, alchimistul din Goldshire, care le ofera ce le trebuie pentru o intalnire secreta.",al={"cine o ajuta pe maybell","ajutoarele familiei stonefield"}}},fx={c4338ded={q="Cine este Maybell Maclure?",a="Maybell Maclure este o tanara femeie umana care locuieste la Maclure Vineyards, in Elwynn Forest. Este prinsa la mijloc intr-o dusmanie apriga si indelungata dintre familia ei si vecinii lor, Stonefields, dupa ce s-a indragostit profund de Tommy Joe Stonefield.",al={"cine este Maybell","cine este Maybell Maclure","povestea lui Maybell Maclure"}},["9f94442c"]={q="De partea cui este Maybell Maclure?",a="Este o supusa loiala a Alliance si o fiica a familiei Maclure. Totusi, cand vine vorba de rivalitatea meschina si plina de resentimente dintre Maclures si Stonefields, respinge cu totul ura si alege dragostea pentru Tommy Joe in locul ranchiunei familiei.",al={"Maybell este de partea Aliantei","de partea cui este Maybell","factiunea lui Maybell"}},cbd5fa72={q="Ce isi doreste Maybell Maclure?",a="Maybell nu-si doreste nimic mai mult decat sa fie alaturi de Tommy Joe Stonefield. Cum familiile lor se urasc cu inversunare, ea cere ajutorul calatorilor milosi si al confidentilor de incredere pentru a gasi modalitati de a se intalni cu el pe ascuns, fara sa fie prinsi.",al={"ce vrea Maybell","scopul lui Maybell Maclure","de ce are Maybell nevoie de ajutor"}},b079e731={q="De ce se afla Maybell Maclure aici?",a="Maybell locuieste la Maclure Vineyards, mosia familiei sale din sudul Elwynn Forest. Este tinuta pe terenul podgoriei sub supravegherea atenta a rudelor, sperand sa gaseasca prilejul de a fugi si a-si vedea iubitul.",al={"de ce este Maybell Maclure aici","de ce este Maybell la vii"}},["26be6d7a"]={q="De cine este legata Maybell Maclure?",a="Maybell face parte din familia Maclure, proprietara podgoriei. Este indragostita de Tommy Joe Stonefield, mostenitorul fermei rivale Stonefield, si pastreaza legaturi secrete cu Gramma Stonefield, care sustine povestea lor de dragoste clandestina.",al={"relatiile lui Maybell Maclure","cu cine este ruda Maybell","legaturile lui Maybell"}}},fp="15,191,29.299.0,26.285.1,47.179.0,48.146.1,34.136.0,35.172.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Mebok Mizzyrix",s="Mebok Mizzyrix este un antreprenor goblin intreprinzator care locuieste in orasul-port Ratchet. Dornic sa transforme in profit reactivi neobisnuiti din salbaticie, el angajeaza aventurieri de ocazie sa adune flora si fauna neobisnuite din Barrens si din imprejurimi. Cel mai notoriu proiect al sau presupune prepararea unei bauturi comerciale care imbunatateste intelectul, folosind coarne de raptor.",h="Mebok Mizzyrix este un antreprenor goblin intreprinzator care locuieste in orasul-port Ratchet.",kw={"barrens","tuberculi Blueleaf","Mebok","Mizzyrix","coarne de rapitor","Ratchet","bauturi inteligente","Steamwheedle"},ang={["faction:Alliance"]="Coborand din barca venita din Booty Bay in Ratchet, teritoriu neutru, exploratorii din Alliance pot indeplini sarcinile lui Mebok fara teama de garzile ostile.",["faction:Horde"]="Trecerea prin Ratchet in drum prin Barrens le ofera calatorilor Hordei o modalitate usoara de a castiga bani, starpind fiarele periculoase din apropiere.",["profession:Cooking"]="Aventurierii gurmanzi vor considera cel mult indoielnice retetele culinare si de bauturi ale lui Mebok, avand in vedere insistenta sa de a fermenta corn de rapitor macinat.",["profession:Herbalism"]="Fascinatia lui Mebok pentru specimene neobisnuite precum tuberculii Blueleaf dezvaluie latura mai salbatica si comerciala a culegerii florei unice din Kalimdor."},sec={{t="Un alchimist intreprinzator",b="Lucrand din portul neutru si aglomerat Ratchet, Mebok Mizzyrix intruchipeaza spiritul clasic Steamwheedle, bazat pe oportunism neobosit. Desi Ratchet le ofera servicii marinarilor, piratilor si negustorilor de toate soiurile, Mebok isi indreapta privirea agera spre salbaticia din Kalimdor. In loc sa exploateze minereu obisnuit sau sa faca negot cu tesaturi banale, cauta curiozitati biologice rare, despre care crede ca pot fi rafinate in amestecuri si marfuri extrem de profitabile."},{t="Misiunea pentru Smart Drinks",b="Cea mai importanta initiativa comerciala a lui Mebok este o 'bautura desteapta' de marca, menita sa sporeasca artificial inteligenta celui care o consuma. Convins ca siretenia si ferocitatea rapitoarelor locale se trag din coarnele care le incununeaza boturile, Mebok le cere vinatorilor sa adune coarne intregi din toate tinuturile Barrens. Pentru el, etica si gustul trec pe planul al doilea fata de potentialul comercial brut, atita timp cit clientii platitori cred ca bautura isi face efectul."},{t="Reactiivi exotici si flora",b="Pe langa elixirurile obtinute din rapitori, Mebok are nevoie constant de alte specimene bizare. De la colectarea oualor volatile de paianjen Deepmoss pana la comanda de recuperare a unor tuberculi Blueleaf rari, ingropati adanc in maracinii din Razorfen Kraul, indeletnicirile sale ii imping mereu pe mercenarii indrazneti in tinuturi primejdioase. Daca un organism are proprietati neobisnuite, Mebok este sigur ca exista o cale de a-l imbutelia si vinde."}},faq={{q="Cine este Mebok Mizzyrix?",a="Mebok Mizzyrix este un negustor goblin si un alchimist cu planuri ambitioase, aflat in orasul-port neutru Ratchet, in Barrens. El contracteaza aventurieri pentru a aduna vietati salbatice neobisnuite si parti de plante necesare proiectelor sale comerciale.",al={"cine este Mebok","povestea lui Mebok Mizzyrix","goblinul Mebok din Ratchet"}},{q="Ce sunt Smart Drinks?",a="Smart Drinks sunt tonice experimentale care sporesc intelectul si pe care Mebok Mizzyrix spera sa le prepare si sa le vanda. El crede ca macinarea coarnelor raptoarelor istete din Barrens va transmite bauturii instinctele ascutite si viclenia acestora.",al={"Smart Drink","misiunea Smart Drinks","potiune din corn de rapitor"}},{q="Unde poate fi gasit Mebok Mizzyrix?",a="Poate fi gasit printre cladirile din orasul-port Ratchet, pe coasta estica a Barrens, unde pot ajunge atat calatorii din Horde, cat si cei din Alliance.",al={"locatia lui Mebok","unde este Mebok","gaseste-l pe Mebok Mizzyrix"}},{q="De ce vrea Mebok coarne de rapitor?",a="Mebok presupune ca inteligenta sireata a raptoarelor care cutreiera Barrens este concentrata in coarnele lor. Planuieste sa le macine si sa le foloseasca drept ingredientul activ principal in bauturile sale care sporesc inteligenta.",al={"de ce coarne de rapitor","scopul cornului de rapitor","ce face Mebok cu coarnele"}},{q="De ce trimite Mebok oameni la Razorfen Kraul?",a="Recruteaza aventurieri sa patrunda in Razorfen Kraul si sa dezgroape tuberculi Blueleaf cu ajutorul unui caine de urma dresat, cautand planta rara pentru proprietatile ei botanice neobisnuite si pretioase.",al={"de ce Razorfen Kraul","misiunea lui Mebok din RFK","tuberculi Blueleaf din RFK"}},{q="Lucreaza Mebok pentru Horde sau Alliance?",a="Mebok este un membru independent al Steamwheedle Cartel in Ratchet, teritoriu neutru. Este loial banului si face cu placere schimburi si contracte cu membrii ambelor factiuni.",al={"este mebok din horde","este mebok din alliance","factiunea lui mebok"}}},fx={["55f078f0"]={q="Ce vrea Mebok Mizzyrix?",a="Pe Mebok il mana dorinta de a nascoci creatii alchimice noi si ciudate—mai ales experimentala sa 'bautura desteapta.' Pentru a-si perfectiona retetele bizare, trimite aventurieri sa scotoceasca Barrens si adancurile sale periculoase in cautarea unor ingrediente neobisnuite, de la coarne intregi de raptor pana la mostre rare de radacini si oua de paianjen.",al={"ce vrea mebok","de ce are nevoie mebok","scopul lui mebok mizzyrix"}},c521482b={q="De ce se afla Mebok Mizzyrix in Ratchet?",a="Ratchet este principalul oras-port pentru goblinii ambitiosi care au nevoie de acces rapid la resursele salbatice din Kalimdor. De la baza sa de aici, Mebok poate angaja cu usurinta mercenari sositi din oricare factiune, ca sa patrunda in savana primejdioasa si sa culeaga exemplarele salbatice necesare experimentelor sale.",al={"de ce e mebok aici","de ce e mebok in ratchet","mebok mizzyrix barrens"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="Melithar Staghelm"}
P.entries["npc:melor-stonehoof"] = {n="Melor Stonehoof"}
P.entries["npc:menara-voidrender"] = {n="Menara Voidrender"}
P.entries["npc:merissa-stilwell"] = {n="Merissa Stilwell",s="La Northshire Abbey, Merissa Stilwell ii intampina pe nou-veniti in Northshire Valley. Tanara localnica Human le ofera un salut voios si o mana de ajutor celor care se antreneaza in apropiere.",h="La Northshire Abbey, Merissa Stilwell ii intampina pe nou-veniti in Northshire Valley.",kw={"elwynn","merissa","northshire","stilwell"},ang={["faction:Alliance"]="Ca recrut al Alliance care paraseste claustrul adapostit din Northshire, gasesti in Merissa ospitalitatea calda a tinutului Elwynn, inainte ca realitatea aspra a amenintarii Defias sa-si faca simtita prezenta."},sec={{t="O fata primitoare in Northshire",b="Merissa Stilwell intampina recruti noi sositi in Northshire Valley, din locul ei de la Northshire Abbey. Le ofera nou-venitilor ospitalitate simpla si sfaturi practice despre odihna si orientare. Numele ei de familie este purtat si de mestesugari si gospodari din tot regatul, inclusiv de fierarul Jordan Stilwell si aparatorul din Westfall, Daphne Stilwell. Merissa ramane o prezenta pasnica locala in mijlocul tensiunilor tot mai mari din regat."}},faq={{q="Cine este Merissa Stilwell?",a="Merissa Stilwell este o locuitoare Human prietenoasa din Northshire Abbey, in Elwynn Forest. Le ofera sfaturi si o primire calduroasa calatorilor care ajung acolo.",al={"Merissa Stilwell","cine este Merissa","fata Stilwell din Northshire"}},{q="Unde o pot gasi pe Merissa Stilwell?",a="O poti gasi pe Merissa Stilwell la Northshire Abbey, in Northshire Valley din Elwynn Forest.",al={"locatia lui Merissa Stilwell","unde este Merissa","gaseste-o pe Merissa"}},{q="Este Merissa inrudita cu ceilalti Stilwell din regat?",a="Merissa Stilwell are acelasi nume de familie ca fierarul Jordan Stilwell si Daphne Stilwell din Westfall. Duce o viata linistita la Northshire Abbey, primind calatori in loc sa lupte cu banditii sau sa faureasca lame.",al={"familia stilwell","ruda lui daphne stilwell","ruda lui jordan stilwell"}},{q="Ofera Merissa Stilwell vreo misiune?",a="Nu. Merissa Stilwell nu are nicio sarcina pentru calatori; doar ii saluta pe nou-venitii care trec prin Northshire.",al={"misiuni merissa","misiunea lui merissa stilwell"}}},fx={a071eba0={q="De partea cui este Merissa Stilwell?",a="Merissa Stilwell este o supusa loiala a Grand Alliance si a Kingdom of Stormwind. Locuind in pace la Northshire Abbey, ea le ureaza bun venit calatorilor si recrutilor care sosesc in vale.",al={"factiunea lui Merissa Stilwell","este Merissa Stilwell din Alliance"}},["57a6fac4"]={q="De ce se afla Merissa Stilwell in Northshire?",a="Merissa isi petrece zilele prin preajma Northshire Abbey. Ca multi oameni de rand ai regatului, isi duce viata in Elwynn Forest si ii intampina pe nou-venitii care sosesc in vale.",al={"de ce este Merissa Stilwell aici","ce face merissa in Northshire"}}},fp="16,178,30.433.0,24.149.0,34.93.0,57.206.0,39.103.0"}
P.entries["npc:merrin-rockweaver"] = {n="Merrin Rockweaver",s="Merrin Rockweaver este o cercetatoare pitica ce reprezinta Explorers' League in Wetlands. Dupa ce o infestare violenta cu rapitori a coplesit Whelgar's Excavation Site, ea si-a gasit adapost alaturi de Prospector Whelgar pe o creasta cu vedere spre sit.",h="Merrin Rockweaver este o cercetatoare pitica ce reprezinta Explorers' League in Wetlands.",kw={"Explorers' League","Merrin Rockweaver","raptori","treaba de unelte","Wetlands","situl de excavatii al lui Whelgar","refugiul lui Whelgar"},ang={["faction:Alliance"]="Merrin reprezinta prezenta academica a Ironforge in Wetlands, iar protejarea cercetarilor ei ajuta la mentinerea firavei pozitii a Alliance in salbaticia mlastinoasa.",["race:Dwarf"]="Pentru aventurierii pitici, sa-l ajuti pe Merrin tine de mostenirea nationala: inseamna sa protejezi pretioasele relicve Titan si documentele istorice pe care Explorers' League si-a riscat viata pentru a le descoperi."},sec={{t="Stramutati de sapaturi",b="Merrin Rockweaver a calatorit in Wetlands in numele Explorers' League din Ironforge, pentru a scoate la iveala stravechi secrete ale titanilor ingropate sub noroi. Expeditia s-a incheiat dezastruos cand oasele uriase dezgropate au atras rapitori la locul sapaturilor. Bestiile preistorice feroce au napadit transeele, silindu-i pe Merrin si pe membrii supravietuitori ai echipei sa-si abandoneze echipamentul, notitele si munca. Acum, ea este blocata impreuna cu putinii supravietuitori pe o culme deasupra ruinelor invadate."},{t="Salvarea operatiunii",b="Prinsi pe povarnis, supravietuitorii refuza sa lase expeditia sa se sfarseasca intr-un esec total. In timp ce Ormer Ironbraid planuieste sa se razbune pe fiare, iar Prospector Whelgar cauta fragmentele de tablite lasate in transeele napadite de rapitori, gandurile lui Merrin se indreapta catre sotul ei, Tarrel, care nu a mai primit vesti de la ea de saptamani intregi. Ea se bazeaza pe cercetasul trimis de Longbraid sa gaseasca echipa, ca sa-i duca sotului ei vestea despre situatia lor."}},faq={{q="Cine este Merrin Rockweaver?",a="Merrin Rockweaver este o arheoloaga pitica afiliata Explorers' League din Ironforge. Era stationata la Whelgar's Excavation Site, in Wetlands, inainte ca raptoarele sa invadeze zona de excavare.",al={"povestea lui Merrin Rockweaver","cine este Merrin","piticul din Wetlands Merrin"}},{q="De ce este blocata deasupra sitului de excavare?",a="Raptorii pestriti, atrasi de oasele mari descoperite de echipa, au coplesit zona de sapaturi de dedesubt, iar multi si-au pierdut viata. Ormer Ironbraid i-a aparat pe Merrin si Prospector Whelgar in timp ce fugeau spre stanca din apropiere, unde au ramas prinsi.",al={"de ce este Merrin la refugiu","Merrin la Whelgar's Retreat","ce s-a intamplat cu tabara ei"}},{q="Cu ce are nevoie de ajutor Merrin?",a="Merrin are nevoie de cineva care sa-i duca sotului ei, Tarrel, o scrisoare care explica dezastrul; el este foarte ingrijorat de cand scrisorile ei au incetat sa mai soseasca.",al={"misiunile lui merrin","sarcinile lui Merrin Rockweaver","povestea din spatele uneltelor"}},{q="Ce incerca sa gaseasca expeditia?",a="Ca majoritatea operatiunilor Explorers' League, sapaturile din Wetlands au fost organizate pentru a descoperi artefacte stravechi legate de stramosii piticilor si de misterioasele relicve Titan ascunse prin Khaz Modan.",al={"ce cauta ei","scopul sitului de excavare"}}},fx={["86a5e24a"]={q="De partea cui este Merrin Rockweaver?",a="Merrin Rockweaver este ferm de partea piticilor din Ironforge si a Alliance. In calitate de topograf activ si membru al Explorers' League, loialitatea ei le apartine carturarilor si excavatorilor trimisi din Ironforge pentru a descoperi originile stravechi ale poporului lor in Khaz Modan.",al={"factiunea lui Merrin Rockweaver","loialitatea lui Merrin Rockweaver","cui ii slujeste Merrin"}},f33c6ea8={q="Cu cine are legaturi Merrin Rockweaver?",a="Merrin insoteste expeditia lui Prospector Whelgar la situl de excavare din Wetlands. Ormer Ironbraid ii ajuta sa-si apere tabara de rapitorii care o inconjoara.",al={"legaturile lui Merrin Rockweaver","asociatii lui Merrin Rockweaver","cu cine lucreaza Merrin"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {n="Miles Welsh"}
P.entries["npc:milton-sheaf"] = {n="Milton Sheaf",s="In Stormwind Keep, Milton Sheaf pazeste istoria scrisa a regatului. Se ocupa de Royal Library si le cere calatorilor din Alliance sa recupereze carti si documente pierdute.",h="In Stormwind Keep, Milton Sheaf pazeste istoria scrisa a regatului.",kw={"carti","istorie","bibliotecar","milton sheaf","royal library","stormwind keep","tomuri"},ang={["faction:Alliance"]="Ca drumet din Alliance, il poti ajuta pe Milton Sheaf sa pastreze mostenirea consemnata a regatelor Human si a Alliance in ansamblu.",["race:Human"]="Ca Human, impartasesti o istorie pe care Milton Sheaf o protejeaza, pastrand cronicile care au supravietuit caderii si reconstructiei Stormwind."},sec={{t="Paznicul istoriei Stormwind",b="Milton Sheaf ingrijeste Royal Library din Stormwind Keep. In timp ce curtea se ocupa de politica, disputele nobiliare si problemele militare, el pastreaza inregistrarile scrise. Considera ca pastrarea unor istorii exacte despre Alliance si Eastern Kingdoms este o datorie, mai ales in vremuri de razboi, pierderi si instabilitate."},{t="Recuperarea tomurilor pierdute",b="Milton Sheaf trimite calatori sa recupereze carti raspandite prin tinuturi. Volumele se uzeaza de la folosire, iar documentele zac in arhive monahale, avanposturi indepartate si ruine uitate. Ii trimite pe aventurierii Alliance din Northshire Abbey pana la Southshore, in nord, pentru a recupera carti ratacite, a cerceta texte antice si a readuce in siguranta manuscrise rare la fortareata."}},faq={{q="Cine este Milton Sheaf?",a="Milton Sheaf este un carturar Human care se ocupa de Royal Library din Stormwind Keep, in Stormwind City. El administreaza cartile si cronicile regatului.",al={"cine este Milton Sheaf","rolul lui Milton Sheaf","bibliotecar din Stormwind"}},{q="Unde il pot gasi pe Milton Sheaf?",a="Il poti gasi pe Milton Sheaf in aripa Royal Library din Stormwind Keep, chiar langa coridoarele principale ale palatului.",al={"locatia lui Milton Sheaf","unde este Milton Sheaf","locatia bibliotecii din Stormwind"}},{q="De ce are nevoie Milton Sheaf de aventurieri?",a="Milton Sheaf se bazeaza pe aventurierii calatori din Alliance sa gaseasca manuscrise istorice, sa inlocuiasca volumele deteriorate si sa colaboreze cu invatati si clerici din tot regatul pentru a imbogati arhivele Royal Library.",al={"misiunile lui milton sheaf","ce vrea milton","de ce ofera misiuni"}},{q="Milton Sheaf interactioneaza cu alti carturari din regat?",a="Da. Milton Sheaf pastreaza legaturi cu arhivistii manastirii si cu invatatii religiosi, inclusiv cu Brother Paxton din Northshire Valley, pentru a pastra invataturile sacre si documentele istorice.",al={"Milton din Northshire","Milton, fratele lui Brother Paxton","legaturile lui Milton"}}},fx={["440d1fb9"]={q="De partea cui este Milton Sheaf?",a="Milton Sheaf slujeste Kingdom of Stormwind si Alliance. Stationat chiar in Stormwind Keep, lucreaza direct pentru arhivele regale ale monarhului, catalogand istoria si pastrand cunostinte pentru invatatii si conducatorii regatului.",al={"factiunea lui Milton Sheaf","pe cine slujeste Milton Sheaf","Milton Sheaf face parte din Alianta"}},["1fad6188"]={q="De ce se afla Milton Sheaf aici, in Stormwind Keep?",a="Milton raspunde de administrarea si intretinerea Royal Library. El ingrijeste vasta colectie de suluri, tomuri si documente istorice a regatului, asigurandu-se ca marturiile esentiale despre trecutul Azerothului raman protejate si accesibile curtii.",al={"de ce este Milton Sheaf in Royal Library","scopul prezentei lui Milton Sheaf aici","de ce este Milton in Stormwind"}}},fp="12,163,36.288.0,21.354.0,20.151.0,30.106.0,39.200.0,62.177.0"}
P.entries["npc:miner-johnson"] = {n="Miner Johnson",s="Miner Johnson este un miner veteran greu de gasit, afiliat Defias Brotherhood, in adancurile din Deadmines. Ascuns intr-o nisa laterala, alaturi de muncitori obisnuiti, acest prospector periculos supravegheaza sapaturile dinaintea utilajelor grele aflate mai jos in subteran. Pentru ca rataceste fara noima prin tunelurile subterane, aventurierii se intalnesc cu el doar din cand in cand.",h="Miner Johnson este un miner veteran greu de gasit, afiliat Defias Brotherhood, in adancurile din Deadmines.",kw={"nisa","Deadmines","Defias","elite","Miner Johnson","Moonbrook","rar","tocator","Westfall"},ang={["faction:Alliance"]="Infrangerea lui Johnson perturba fluxul constant de minereu topibil care ajunge la masinaria de razboi Defias ascunsa sub Moonbrook.",["profession:Mining"]="Pentru cautatorii de minereuri, Johnson intruchipeaza latura aspra si fara de lege a muncii subterane, pazind bogate zacaminte minerale adanc sub Westfall cu sange si tarnacop."},sec={{t="O aparitie rara in adancuri",b="In timp ce sute de muncitori scormonesc filoanele subterane din Deadmines pentru a aproviziona fortareata ascunsa a lui Edwin VanCleef, Miner Johnson se remarca printre ei ca o prezenta neobisnuit de impunatoare. Sta la panda intr-o nisa umbrita, in stanga, inaintea masinilor de taiat uriase din Mast Room, fiind mult mai rezistent si mai agresiv decat muncitorii obisnuiti. Prezenta sa imprevizibila il transforma intr-o tinta legendara pentru exploratorii care strabat tunelurile Defias."},{t="Alimentarea masinariei de razboi Defias",b="Operatiunea clandestina a Defias Brotherhood de sub Moonbrook necesita cantitati uriase de minereu brut pentru fabricarea armelor, consolidarea galeriilor si asamblarea dispozitivelor mecanice. Minerii precum Johnson asigura forta de munca, sapand in filoanele bogate de minereu de sub Westfall. Oricine da peste locul de munca al lui Johnson va descoperi repede ca acesta isi apara zona de excavare cu o fervoare letala."}},faq={{q="Cine este Miner Johnson?",a="Miner Johnson este un miner uman de elita, rar intalnit, aflat in slujba Defias Brotherhood. Munceste in adancul Deadmines, intr-o nisa laterala alaturi de alti muncitori, chiar inainte de utilajul goblin.",al={"povestea Miner Johnson","cine este Miner Johnson","Miner Johnson din Deadmines"}},{q="Unde se afla mai exact Miner Johnson?",a="Poate fi gasit in galeriile superioare din Deadmines, inainte de a ajunge la incaperea in care se afla Sneed si masinaria lui de maruntit. Cauta o mica nisa de excavatie in stanga, unde cativa mineri sapa activ in stanca.",al={"locatia lui Miner Johnson","unde se afla Miner Johnson","cum sa-l gasesti pe Miner Johnson"}},{q="De ce nu se afla mereu acolo Miner Johnson?",a="Miner Johnson este o aparitie rara, adica apare doar ocazional cand o expeditie intra in Deadmines. In locul lui, majoritatea grupurilor care strabat galeriile minei vor gasi un miner obisnuit.",al={"Miner Johnson nu apare","este Miner Johnson rar","rata de aparitie a lui Miner Johnson"}},{q="Face Miner Johnson parte din vreo misiune?",a="Miner Johnson nu este asociat cu nicio recompensa oficiala pentru o misiune. Este pur si simplu o intalnire neasteptata pentru grupurile care exploreaza temnita si au norocul sa-l gaseasca lucrand la filon.",al={"misiunea lui Miner Johnson","are Miner Johnson vreo misiune"}},{q="Ce rol are Miner Johnson in Deadmines?",a="Este un maistru cu experienta sau un sapator-sef care ii ajuta pe cei din Defias Brotherhood sa extraga metale pretioase, piatra si resurse necesare construirii uriasei lor baze subterane si a colosului ascuns.",al={"ce face miner johnson","rolul lui miner johnson"}},{q="Este Miner Johnson mai periculos decat ceilalti mineri?",a="Da. In timp ce sapatorii obisnuiti din Deadmines sunt destul de vulnerabili, Miner Johnson este un combatant de elita, cu mult mai multa vitalitate si putere de atac, iar pentru a-l dobori in siguranta este nevoie de un grup coordonat.",al={"cat de dificil este Miner Johnson","este Miner Johnson un elite"}}},fx={["3a6e6cc9"]={q="De partea cui este Miner Johnson?",a="El este de partea Defias Brotherhood si a fortei lor de munca. Trudind in adancurile Deadmines alaturi de ceilalti muncitori, Miner Johnson impartaseste loialitatea lor fata de rascoala lui Edwin VanCleef si-si foloseste tarnacopul impotriva oricarui intrus care patrunde in fortareata subterana.",al={"fractiunea Miner Johnson","pentru cine lucreaza Miner Johnson","Miner Johnson face parte din Defias"}},c0432457={q="De ce se afla Miner Johnson in Deadmines?",a="Lucreaza intr-o mica nisa de langa tunelurile minei, chiar inainte de tocator, extragand aur si fier pentru Defias Brotherhood. Alaturi de muncitorii de rand, ajuta la furnizarea metalului brut necesar proiectelor secrete ale lui Edwin VanCleef.",al={"de ce se afla miner johnson aici","de ce miner johnson in deadmines","ce l-a adus pe miner johnson aici"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Manifestare minora a Pamantului"}
P.entries["npc:minor-manifestation-of-water"] = {n="Manifestare minora a apei"}
P.entries["npc:misha"] = {n="Misha",s="Misha este ursul loial care il insoteste pe Rexxar, Campionul Hordei. Rataceste cu credinta prin Kalimdor, alaturi de semicapcaunul stapan al fiarelor.",h="Misha este ursul loial care il insoteste pe Rexxar, Campionul Hordei.",kw={"urs","stapan al fiarelor","desolace","feralas","misha","rexxar","stonetalon"},ang={["class:Hunter"]="Pentru vanatori, Misha intruchipeaza idealul suprem al unui companion animal: un parteneriat de-o viata, indestructibil, cladit pe respect reciproc, nu pe simpla dominare.",["faction:Horde"]="Misha a luptat alaturi de Rexxar pentru a asigura libertatea tinerei Horde la Theramore Isle, castigand respectul tacut al veteranilor din Durotar."},sec={{t="O legatura fara hotare",b="Misha este un urs brun care il insoteste pe ratacitorul Rexxar, un spirit singuratic care are mai multa incredere in fiare decat in oameni. Impreuna au cladit o legatura puternica si protectoare, care a rezistat nenumaratelor tinuturi salbatice si batalii sangeroase."},{t="Aparatorul din Durotar",b="Misha este mult mai mult decat un animal domesticit; este o razboinica incercata. A luptat alaturi de Rexxar in conflictul crunt impotriva Marelui Amiral Daelin Proudmoore de la Theramore Isle, ajutand la asigurarea supravietuirii tinerei Horde. Cand nu se afla in lupta, simturile ei ascutite si forta sa sunt o prelungire a vointei lui Rexxar."},{t="Salbaticia din Kalimdor",b="In prezent, calatorii care strabat drumurile lungi prin Stonetalon Mountains, Desolace si Feralas il pot zari pe Misha mergand tacut langa Rexxar. Desi este destul de feroce incat sa sfasie orice pradator nesabuit care-i ameninta, ea ramane sprijinul statornic al lui Rexxar intr-o lume altminteri de neincredere."}},faq={{q="Cine este Misha?",a="Misha este o ursoaica bruna feroce si tovarasa de-o viata a lui Rexxar, Campionul Horde. Hoinaresc impreuna prin tinuturile salbatice din centrul Kalimdorului.",al={"ursul lui Rexxar","cine este ursul alaturi de Rexxar","ursul Misha"}},{q="Unde poate fi gasit Misha acum?",a="Misha cutreiera drumurile lungi de patrulare din Stonetalon Mountains, Desolace si Feralas, mergand cu credinta alaturi de Rexxar in ratacirile sale nesfarsite.",al={"locatia lui misha","unde se afla misha","gaseste-l pe misha"}},{q="A participat Misha la intemeierea Durotar?",a="Da. Dupa Third War, Misha l-a insotit pe Rexxar in lupta impotriva fortelor lui Grand Admiral Daelin Proudmoore de la Theramore Isle, pentru a apara Horde aflata la inceput de drum.",al={"Misha din Theramore","s-a luptat Misha cu Daelin","Misha in al Treilea Razboi"}},{q="Este Misha ostila fata de jucatorii din Alliance?",a="Da. In calitate de insotitoare a Campionului Horde, Misha il va apara cu inversunare pe Rexxar si va ataca orice intrusi din Alliance care se apropie prea mult.",al={"poate alianta sa-l atace pe Misha","este Misha agresiv"}},{q="De ce prefera Rexxar bestii precum Misha in locul oamenilor?",a="Dezamagit de inselaciunile si razboaiele raselor umanoide, Rexxar a ales singuratatea salbaticiei. El crede ca fiarele sunt directe si sincere, iar in Misha a gasit un tovaras lipsit de tradare.",al={"de ce tine Rexxar bestii","ursul insotitor al lui Rexxar"}}},fp="5,140,16.243.0,19.303.0,17.310.0,13.157.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="Misha Tor'kren"}
P.entries["npc:mitsuwa"] = {n="Mitsuwa",s="Mitsuwa este un troll Darkspear aflat la Zoram'gar Outpost, pe coasta cetoasa din Ashenvale. Profund tulburat de ambuscada in care au cazut rudele sale calatoare, el cheama campionii Horde sa razbune mortii si sa recupereze talismanele spirituale furate.",h="Mitsuwa este un troll Darkspear aflat la Zoram'gar Outpost, pe coasta cetoasa din Ashenvale.",kw={"Ashenvale","Darkspear","furbolg","Marukai","Mitsuwa","Thistlefur","troll","amuleta trollului","Zoram'gar"},ang={["faction:Horde"]="Zoram'gar Outpost este o garnizoana izolata si asediata; ajutand-o pe Mitsuwa, intaresti prezenta primejdioasa a Horde impotriva bestiilor salbatice si a cercetasilor Alliance din tinuturile vestice ale Kalimdor.",["race:Troll"]="Chemarea lui Mitsuwa la arme atinge o coarda profunda pentru aventurierii Darkspear: recuperarea amuletelor sacre ale stramosilor, jefuite de marauderi furbolg neciopliti, le aduce pace fratilor si surorilor lor ucisi."},sec={{t="Razbunarea pentru rudele cazute",b="Aflat la indepartatul Zoram'gar Outpost, pe tarmul Zoram Strand, Mitsuwa slujeste Horde alaturi de tovarasul sau Marukai. Cand un grup de trolls aflati in drum spre tabara a fost prins intr-o ambuscada si macelarit de agresivii furbolgi Thistlefur din nordul Ashenvale, Mitsuwa a socotit pierderea o ofensa grava. Manat de datorie si manie, el ii indruma pe razboinicii in putere spre culcusurile Thistlefur, ca sa recupereze amuletele troll furate, asigurandu-se ca spiritele celor din neamul sau sunt cinstite si ca bunurile lor sacre sunt smulse din ghearele fiarelor."}},faq={{q="Cine este Mitsuwa?",a="Mitsuwa este un jungle troll Darkspear care locuieste la Zoram'gar Outpost, in nord-vestul Ashenvale. Vegheaza asupra avanpostului de frontiera alaturi de tovarasul sau Marukai si coordoneaza razbunarea impotriva amenintarilor ostile din regiune.",al={"mitsuwa","cine este mitsuwa","povestea lui mitsuwa"}},{q="Ce s-a intamplat cu trolii care calatoreau spre Zoram'gar?",a="Un grup de troli care traversa Ashenvale pentru a intari sau vizita Zoram'gar Outpost a fost prins intr-o ambuscada si masacrat de furbolgii Thistlefur bastinasi, care i-au jefuit pe calatorii cazuti de bunurile personale.",al={"troli morti in ashenvale","atacul troliilor thistlefur"}},{q="De ce sunt talismanele troll atat de importante pentru Mitsuwa?",a="Amuletele au insemnatate spirituala si culturala pentru tribul Darkspear. Sa lasi relicve sacre in mainile furbolgilor Thistlefur dupa un macel brutal este o profanare cumplita a spiritelor celor ucisi.",al={"de ce amulete troll","motivul misiunii cu amuleta troll"}},{q="Unde se afla talismanele?",a="Amuletele au fost luate de furbolgii Thistlefur si duse in satul si vizuina lor mizera, aflate in nordul Ashenvale, la est de Zoram Strand.",al={"unde sunt talismanele troll","locatia din thistlefur village"}}},fx={["24ae2c07"]={q="De partea cui este Mitsuwa?",a="Mitsuwa este loial Horde si locuieste alaturi de ai sai la Zoram'gar Outpost, pe coasta Ashenvale. Lucreaza indeaproape cu ceilalti calatori ai Horde si se bazeaza pe aventurierii Horde pentru a razbuna camarazii cazuti.",al={"factiunea lui Mitsuwa","este Mitsuwa de partea Horde","cui ii slujeste Mitsuwa"}},ec72a5f0={q="Ce isi doreste Mitsuwa?",a="Mitsuwa cauta sa faca dreptate unui grup de troli tovarasi, macelariti in drum spre Zoram'gar Outpost. Furbolgii Thistlefur, agresivi, i-au atacat prin surprindere pe calatori si le-au furat amuletele sacre ale trolilor, iar Mitsuwa vrea ca aceste mosteniri furate sa fie recuperate de la bestii.",al={"scopul lui Mitsuwa","de ce are nevoie Mitsuwa","misiunea lui Mitsuwa"}},b936450a={q="De ce se afla Mitsuwa aici, la Zoram'gar Outpost?",a="Mitsuwa este stationat la Zoram'gar Outpost, o tabara indepartata a Horde, pe tarmul vestic din Ashenvale. De aici, supravegheaza salbaticia din imprejurimi si are grija de calatorii care infrunta drumurile primejdioase prin tinuturile furbolgilor si ale elfilor night elf.",al={"de ce este Mitsuwa in Zoram'gar","scopul lui Mitsuwa in Ashenvale","de ce este Mitsuwa aici"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {n="Monte Gazlowe"}
P.entries["npc:moon-priestess-amara"] = {n="Moon Priestess Amara"}
P.entries["npc:mor-rogal"] = {n="Mor'rogal",s="Mor'rogal este un tauren care locuieste la Sun Rock Retreat, in Stonetalon Mountains. El este sfatuitor si indrumator pentru calatorii care cauta glorie si primejdii in adancurile subterane accidentate ale stancilor.",h="Mor'rogal este un tauren care locuieste la Sun Rock Retreat, in Stonetalon Mountains.",kw={"Boulderslide Ravine","Earthen Arise","Mor'rogal","Morrogal","Stonetalon","Sun Rock Retreat","Tauren"},ang={["faction:Horde"]="Pentru calatorii care ajung in refugiul Sun Rock Retreat, Mor'rogal ofera informatii esentiale despre amenintarile care pandesc in stancariile din afara hotarelor asezarii.",["race:Tauren"]="Mor'rogal intruchipeaza respectul taurenilor pentru incercarile fizice si spirituale, considerand adancile scobituri de piatra din Kalimdor un pamant sacru pe care sa-si dovedeasca valoarea."},sec={{t="Observator in stancarii",b="Aflat la adapostul din Sun Rock Retreat, Mor'rogal este foarte interesat de crapaturile adanci si de pesterile care brazdeaza Stonetalon Mountains. Intelegand ca trecatorile subterane intortocheate ale regiunii ascund atat mari bogatii, cat si primejdii mortale, el ii trimite pe curajosii ratacitori ai Horde sa cerceteze locuri primejduite precum Boulderslide Ravine. Pentru Mor'rogal, explorarea acestor adancuri periculoase nu este doar o chestiune de supravietuire, ci si o incercare a spiritului celor care isi urmeaza inima si sufletul in cautarea gloriei."}},faq={{q="Cine este Mor'rogal?",a="Mor'rogal este un tauren care ofera misiuni in Sun Rock Retreat, in Stonetalon Mountains. El serveste drept calauza locala, indemnandu-i pe aventurierii Horde sa-si incerce puterile in pesterile si ravenele periculoase raspandite prin masivul stancos.",al={"morrogal","cine este mor'rogal","povestea lui mor rogal"}},{q="Unde il pot gasi pe Mor'rogal?",a="Il poti gasi stand in Sun Rock Retreat, principalul avanpost al Horde, ascuns printre piscurile din centrul Stonetalon Mountains.",al={"locatia lui Mor'rogal","unde este Mor'rogal","locul numit Morrogal"}},{q="Ce sarcini ofera Mor'rogal?",a="Mor'rogal recruteaza campioni capabili sa patrunda in pestera din Boulderslide Ravine, unde kobolzii extrag cu disperare cristale Resonite, apoi sa-l ucida pe Goggeroc, un Earthen adormit pe care kobolzii l-au dezgropat.",al={"misiunile lui mor'rogal","ce doreste mor'rogal"}},{q="De ce se concentreaza Mor'rogal asupra pesterilor si ravenelor?",a="Mor'rogal crede ca pesterile subterane primejdioase din Stonetalon ascund aventuri adevarate si incercari ale tariei spirituale, oferind glorie si bogatii celor dispusi sa-si riste viata.",al={"de ce sunt pesterile","pesterile Mor'rogal"}}},fx={["9b06cf83"]={q="De partea cui este Mor'rogal?",a="Mor'rogal este de partea Horde si a semenilor sai taureni. Stationat in Sun Rock Retreat, un avanpost izolat al Horde, sus, in Stonetalon Mountains, ii indruma si le da misiuni aventurierilor care slujesc interesele Horde in regiune.",al={"factiunea lui Mor'rogal","Mor'rogal, Hoarda sau Alianta","loialitatea lui Mor'rogal"}},["27de9984"]={q="Ce vrea Mor'rogal?",a="Mor'rogal cauta aventurieri neinfricati, dispusi sa infrunte pesterile si ravenele primejdioase din Stonetalon Mountains. El trimite cercetasi in locuri ostile precum Boulderslide Ravine, indemnand spiritele indraznete sa se confrunte cu pericolele subterane ale pamantului, in schimbul onoarei si bogatiilor.",al={"scopurile lui mor'rogal","ce face mor'rogal","scopul misiunilor lui mor'rogal"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.1,46.188.0"}
P.entries["npc:morgan-pestle"] = {n="Morgan Pestle",s="In Stormwind, Morgan Pestle conduce Pestle's Apothecary din Trade District. Lucreaza impreuna cu fratele sau William Pestle, in Goldshire, ocupandu-se de provizii si cercetari alchimice pentru capitala.",h="In Stormwind, Morgan Pestle conduce Pestle's Apothecary din Trade District.",kw={"alchimist","morgan pestle","farmacistul Pestle","shipment to stormwind","stormwind","cartierul comercial","william pestle"},ang={["faction:Alliance"]="Daca ajungi in Stormwind din Elwynn ca Adventurer al Alliance, magazinul lui Morgan ofera provizii alchimice practice si livrari in oras.",["profession:Herbalism"]="Morgan se bazeaza pe ingrediente proaspete adunate prin Elwynn Forest si dincolo de aceasta, pentru a-si aproviziona apotecaria din Trade District al Stormwind."},sec={{t="Apotecarul orasului",b="Morgan Pestle vinde produse alchimice, reactivi si remedii practice la Pestle's Apothecary, in Trade District din Stormwind. Fratele sau William are un atelier la Lion's Pride Inn din Goldshire, in timp ce Morgan se ocupa de afacerea familiei in capitala. El primeste provizii din tinuturile rurale, inclusiv lumanari trimise de William."}},faq={{q="Unde il pot gasi pe Morgan Pestle?",a="Il poti gasi pe Morgan Pestle in interiorul Pestle's Apothecary din Trade District, Stormwind City.",al={"locatia lui Morgan Pestle","unde este Morgan Pestle","farmacistul Pestle din Stormwind"}},{q="Ce legatura de rudenie exista intre Morgan Pestle si William Pestle?",a="Morgan Pestle si William Pestle sunt frati si lucreaza amandoi ca alchimisti in Elwynn. Morgan conduce magazinul lor din Stormwind, in timp ce William lucreaza in Goldshire.",al={"fratele lui William Pestle","William si Morgan sunt rude","fratii Pestle"}},{q="Ce rol are in misiunile din Elwynn?",a="Morgan primeste lumanarile pe care William le trimite spre nord din Goldshire, la Pestle's Apothecary, si il plateste bine pe curier pentru livrare.",al={"shipment to stormwind morgan","morgan pestle misiune"}}},fx={["2e5b0856"]={q="Cine este Morgan Pestle?",a="Morgan Pestle este un alchimist uman si negustor care isi desfasoara activitatea in Trade District din Stormwind City. Detine si conduce Pestle's Apothecary, unde le vinde locuitorilor orasului reactivi, remedii si diverse amestecuri alchimice.",al={"cine este Morgan Pestle","povestea lui Morgan Pestle","cine este Pestle"}},ae642a6d={q="De partea cui este Morgan Pestle?",a="Morgan Pestle este un cetatean loial al Alliance. Cu sediul in inima Trade District din Stormwind City, activitatea sa comerciala sustine populatia locala si regatul in ansamblu.",al={"factiunea lui Morgan Pestle","este Morgan Pestle de partea Aliantei","loialitatea lui Morgan Pestle"}},["2ef8a55a"]={q="De ce se afla Morgan Pestle aici?",a="Morgan Pestle locuieste in Stormwind City, unde isi administreaza pravalie, Pestle's Apothecary. Din magazinul sau din animatul Trade District, vinde potiuni si maruntisuri si primeste marfuri de la fratele sau William, care lucreaza in Goldshire.",al={"de ce este morgan pestle in stormwind","morgan pestle in districtul comercial"}}},fp="13,189,19.336.0,31.89.0,47.155.0,40.132.0"}
P.entries["npc:morgan-the-collector"] = {n="Morgan the Collector",s="La Brackwell Pumpkin Patch, Morgan the Collector coordoneaza santajul si strangerea de bunuri pentru Defias in Elwynn Forest. Agent de rang inalt, el organizeaza furturile locale de la ferma, in timp ce garzile din Goldshire supravegheaza zona din apropiere.",h="La Brackwell Pumpkin Patch, Morgan the Collector coordoneaza santajul si strangerea de bunuri pentru Defias...",kw={"Brackwell","Brotherhood","Defias","Dughan","vanatoare de oameni","Morgan","lan de dovleci","sigiliu","The Collector"},ang={["class:Rogue"]="Ca Rogue, poti vedea cum disciplina lui Morgan transforma hoti razleti intr-un sindicat subteran organizat, care finanteaza o insurectie.",["race:Human"]="Ca Human, razbunarea impotriva lui Morgan este o riposta la tradatorii care au transformat fermele pasnice din Stormwind in ascunzatori de banditi fortificate."},sec={{t="Zeciuiala din Elwynn",b="Morgan the Collector sustrage aurul din minele din Elwynn Forest pentru Defias Brotherhood. In timp ce banditii de rand hartuiesc calatorii pe drumuri, el organizeaza jafuri sistematice si strange monedele si proviziile furate pentru reteaua extinsa a Brotherhood. Cartierul sau general se afla la ferma din Brackwell Pumpkin Patch, unde il inconjoara oameni de incredere, printre care Surena Caledon si Erlan Drudgemoor."},{t="Un sigiliu din trecut",b="Morgan poarta un inel-sigiliu distinctiv, care ii atesta autoritatea. Anchetatorii din Goldshire considera inelul o dovada care leaga hotii mascati ce terorizeaza tinuturile din inima regatului de Stonemasons Guild, discreditata dupa ce a reconstruit Stormwind City in urma Second War. Recuperarea inelului dezvaluie cine ii conduce pe banditii din paduri."}},faq={{q="Cine este Morgan the Collector?",a="Morgan este un ofiter de rang inalt al Defias Brotherhood, care strange aurul luat din minele din Elwynn Forest si coordoneaza activitatea banditilor din regiune.",al={"cine este Morgan","povestea lui Morgan","Collector din Elwynn"}},{q="Unde poate fi gasit Morgan?",a="Morgan isi tine marfurile furate in casa fermei de la Brackwell Pumpkin Patch, in estul Elwynn Forest.",al={"locatia lui morgan","unde se afla morgan the collector","casa de la brackwell pumpkin patch"}},{q="De ce il vaneaza Stormwind?",a="Marshal Dughan si autoritatile locale vor ca Morgan sa fie eliminat pentru a destrama conducerea Defias din Elwynn si a recupera dovezi despre cine organizeaza rascoalele din zonele rurale.",al={"de ce sa-l omori pe morgan","tinta vanatorii"}},{q="Ce are special inelul pe care il poarta?",a="Morgan poarta un inel cu sigiliu care le ofera autoritatilor dovezi in timp ce ii investigheaza activitatile din Elwynn Forest.",al={"inelul colectorului","inelul cu sigiliul colectorului","povestea inelului lui Morgan"}}},fx={["8321821e"]={q="De partea cui este Morgan the Collector?",a="Morgan the Collector este un agent devotat al Defias Brotherhood. Nu este un simplu talhar de drumul mare, ci un ofiter al organizatiei criminale, care actioneaza direct impotriva Kingdom of Stormwind si coordoneaza activitatile fratiei in toata inima regiunii Elwynn Forest.",al={"factiunea colectionarului morgan","din ce factiune face parte morgan","morgan este Defias"}},["5f1d52ce"]={q="Ce isi doreste Morgan the Collector?",a="Morgan este capul care coordoneaza operatiunile Defias din Elwynn Forest. Purtand porecla 'the Collector', el urmareste sa adune bogatii, resurse si influenta pentru rascoala Fratiei, intemeind un cap de pod fortificat in campul de dovleci, chiar sub nasul garzilor din Stormwind.",al={"ce incearca sa faca Morgan","scopul lui Morgan Collector","motivul lui Morgan Collector"}},["2a29f808"]={q="De ce se afla Morgan the Collector in Elwynn Forest?",a="Morgan s-a stabilit la Brackwell Pumpkin Patch pentru a conduce personal operatiunile locale ale Defias Brotherhood. Refugiindu-se in ferma alaturi de locotenentii Surena Caledon si Erlan Drudgemoor, el coordoneaza indeaproape banditii care se raspandesc prin regiune.",al={"de ce se afla morgan la Brackwell Pumpkin Patch","ce l-a adus pe morgan aici"}},ceb85f69={q="De cine este legat Morgan the Collector?",a="Inelul sau cu sigiliu devine o dovada in investigatia asupra proscrisilor care tulbura Elwynn Forest si a legaturilor acestora.",al={"cu cine lucreaza Morgan","asociatii lui Morgan, colectorul","Morgan si zidarii"}}},fp="20,229,19.392.0,20.327.1,28.156.0,22.103.0,29.152.0,42.113.1"}
P.entries["npc:morin-cloudstalker"] = {n="Morin Cloudstalker"}
P.entries["npc:motega-firemane"] = {n="Motega Firemane",s="Motega Firemane este un cãrturar tauren stationat la Whitereach Post, in Thousand Needles. Devotat catalogãrii faunei periculoase din canion, isi vede studiile intrerupte de spiritul rãzbunãtor al unui sarpe al vantului si de aventurile nesãbuite ale tanãrului sãu asistent.",h="Motega Firemane este un cãrturar tauren stationat la Whitereach Post, in Thousand Needles.",kw={"Arikara","Cairne Bloodhoof","Kanati Greycloud","Magatha Grimtotem","Motega Firemane","Pao'ka Swiftmountain","Thousand Needles","Whitereach Post"},ang={["class:Hunter"]="Vanatorii gasesc un punct comun cu Motega, care se bazeaza pe iscusiti urmaritori pentru a culege flora canioanelor, a urmari wyvernele din Highperch si a vana spiritul puternic Arikara.",["faction:Horde"]="Motega intruchipeaza expansiunea Horde in tinuturile neimblanzite din Kalimdor, mentinand un avanpost de cercetare precar si aparandu-l pe Marele sef Cairne Bloodhoof de amenintarile spirituale.",["race:Tauren"]="Prin respectul sau pentru natura si devotamentul fata de Cairne Bloodhoof, Motega intruchipeaza etosul taurenilor: sa studieze creaturile Earth Mother, aparandu-si in acelasi timp tribul de spiritele stravechi."},sec={{t="Invatatul canioanelor",b="La patru ani dupa Third War, Motega Firemane a calatorit spre sud, in Thousand Needles, pentru a observa si a consemna fiarele aparte care supravietuiau printre mesetele semete. Insotit de tanarul sau asistent, Pao'ka Swiftmountain - al carui tata protector ezita sa-l lase sa plece din Mulgore - Motega si-a instalat tabara alaturi de Kanati Greycloud la Whitereach Post. Desi menirea sa initiala era sa observe natura in liniste, primejdiile aspre de pe fundul canionului impun necontenit o abordare mai martiala pentru a supravietui."},{t="Mania lui Arikara",b="Cercetarile pasnice ale lui Motega au fost date peste cap de vestea sosita din Freewind Post: Arikara, un spirit serpentin inaripat, feroce si legendar, se intorsese in canioane cautand razbunare impotriva lui Cairne Bloodhoof. Nedumerit de motivul pentru care o asemenea creatura avea ceva de impartit cu marele conducator, Motega a actionat rapid pentru a apara Horde. Le-a poruncit cercetasilor sa adune agava Incendia din bazinul canionului si sa o duca la batrana Magatha Grimtotem din Thunder Bluff, pentru a fi vrajita si transformata intr-o pulbere sacra. Folosind acest preparat, vanatorii au chemat si au ucis spiritul serpentin, apoi i-au dus pielea la Whitereach Post, ca dovada ca nu mai exista niciun pericol pentru Cairne."},{t="Paznicul din Whitereach",b="Arikara nu era singurul pericol care ameninta sederea lui Motega la Whitereach Post. Centaurii Galak din partea locului hartuisera fara incetare tabara si chiar pusesera la cale un complot de asasinare a lui Kanati Greycloud si a adeptilor sai. Ca si cum n-ar fi fost de ajuns, tanarul Pao'ka s-a indepartat de siguranta focului de tabara si a disparut in inaltimile din Highperch, napadite de wyverni. Desi era exasperat de nesabuinta tanarului viteaz, Motega a fost nespus de usurat cand calatorii Horde l-au escortat inapoi, teafar."}},faq={{q="Cine este Motega Firemane?",a="Motega Firemane este un cercetator tauren stationat la Whitereach Post, in Thousand Needles. A venit in canioane pentru a studia fauna locala alaturi de ceilalti bravi si de asistentul sau, Pao'ka Swiftmountain.",al={"povestea lui motega firemane","cine este motega","motega din whitereach"}},{q="Unde poate fi gasit Motega Firemane?",a="Se afla la Whitereach Post, o mica tabara Horde din Thousand Needles, pe drumul din nord-vestul zonei, langa Camp E'thok.",al={"locatia lui motega","unde este motega firemane","harta lui motega firemane"}},{q="De ce este Motega ingrijorat de Arikara?",a="Arikara este un spirit-serpentin razbunator, aparut in Thousand Needles pentru a-l ataca pe Cairne Bloodhoof. Nedumerit de motivul pentru care spiritul poarta pica Marelui Sef, Motega ia amenintarea in serios si le porunceste vanatorilor sa invoce si sa elimine creatura.",al={"cine este arikara","de ce sa-l ucizi pe arikara","arikara cairne"}},{q="Ce rol joaca Magatha Grimtotem in planurile lui Motega?",a="Motega le cere aventurierilor sa adune agave Incendia si sa i le duca lui Magatha Grimtotem, pe Elder Rise, in Thunder Bluff. Magatha isi foloseste cunostintele de shaman pentru a fermeca planta si a o transforma intr-o pulbere sacra, capabila sa-l invoce pe evazivul Arikara.",al={"pulberea incendia a lui magatha","motega si magatha","lore despre misiunea Sacred Fire"}},{q="Ce s-a intamplat cu insotitorul lui Motega, Pao'ka?",a="Pao'ka Swiftmountain s-a ratacit in cuiburile periculoase de viverne din Highperch. Motega era ingrijorat de soarta tanarului, mai ales fiindca tatal lui Pao'ka se opusese atat de mult calatoriei, dar calatorii l-au insotit cu succes inapoi la Whitereach Post.",al={"pao'ka swiftmountain","tauren lipsa highperch","misiunea homeward bound"}},{q="Cu ce alte pericole se confrunta Whitereach Post?",a="Pe langa spiritele razvratite si pradatori, tabara este atacata activ de centaurii Galak din apropiere, care organizeaza ambuscade si comploteaza sa-i asasineze pe Kanati Greycloud si pe ceilalti tauren stationati la avanpost.",al={"amenintarile de la Whitereach Post","centaurii de la Whitereach","planul centaurilor Galak"}}},fx={ca68f68f={q="De partea cui este Motega Firemane?",a="Motega Firemane este loial taurenilor si Horde. Aflat la Whitereach Post alaturi de Kanati Greycloud, el colaboreaza indeaproape cu calatorii Horde si vegheaza asupra intereselor lui Cairne Bloodhoof si ale triburilor aflate sub stindardul Thunder Bluff.",al={"factiunea lui Motega Firemane","Motega Firemane, Hoarda sau Alianta","este Motega de partea Hoardei"}},["8b7dc2d8"]={q="Ce isi doreste Motega Firemane?",a="Motega se concentreaza in primul rand asupra studierii faunei neobisnuite din Thousand Needles, tinand totodata sub observatie tanarul sau companion, Pao'ka Swiftmountain. Insa amenintarile la adresa Thunder Bluff capata repede intaietate. Cand este avertizat cu privire la sarpele-vant razbunator Arikara, incearca sa invoce fiara si s-o distruga inainte sa-l poata pune in pericol pe Cairne Bloodhoof.",al={"ce vrea motega","scopurile lui motega firemane","ce incearca sa faca motega"}},["12cba981"]={q="De ce se afla Motega Firemane aici?",a="Motega a coborat in Thousand Needles pentru a observa si studia fiarele exotice care traiesc pe fundul canionului si pe platourile din jur. Whitereach Post ii serveste drept tabara de baza pentru cercetare, desi necazurile locale - de la tovarasi disparuti la serpi mitici amenintatori - il abat adesea de la preocuparile sale academice.",al={"de ce se afla Motega in Thousand Needles","ce l-a adus pe Motega la Whitereach Post","scopul lui Motega Firemane"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.140.0,38.275.1,56.248.1,44.276.1,45.212.0"}
